INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5787', 'spa', 'Ciego — incapaz de ver, ya sea por ceguera física o por imperceptibilidad espiritual; aplicado a personas, animales y naciones.', 'Ciego — incapaz de ver, ya sea por ceguera física o por imperceptibilidad espiritual; aplicado a personas, animales y naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5788b', 'spa', 'ceguera (sustantivo abstracto que denota la condición de ser ciego, usado para defectos sacrificiales)', 'Este sustantivo abstracto femenino significa ''ceguera'', el estado o condición de no poder ver. En Levítico 22, aparece en una lista de defectos físicos que descalifican a un animal para ser ofrecido en sacrificio. La ley exige que las ofrendas a YHWH sean sin defecto, reflejando tanto la perfección debida a Dios como el principio de que la adoración debe implicar dar lo mejor, no lo defectuoso ni lo indeseado. El término se usa de manera abstracta para expresar lo concreto: un animal ciego. Este uso refleja el patrón común del hebreo de emplear sustantivos abstractos (ceguera) para representar realidades concretas (criaturas ciegas), poniendo énfasis en la condición descalificante misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5789', 'spa', 'prestar ayuda, acudir en socorro, apresurarse (verbo raro, posiblemente del árabe ''socorrer''; texto incierto)', 'Este verbo aparece una sola vez y significa prestar ayuda, acudir en socorro o apresurarse. La raíz hebrea podría estar relacionada con vocablos árabes y nabateos que denotan auxilio y socorro. En Joel, el texto convoca a las naciones al valle del juicio, instándolas a apresurarse y venir. Sin embargo, existe considerable incertidumbre textual: varios eruditos proponen lecturas alternativas como ''apresurarse'' o ''congregarse''. A pesar de estas cuestiones, el contexto describe claramente una convocatoria dramática para que las naciones se reúnan con presteza ante el juicio de Dios en el valle de la decisión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5790', 'spa', 'ayudar, sostener, sustentar (muy incierto; posible aramaísmo, o texto corrupto)', 'Esta forma verbal en infinitivo aparece en un pasaje textualmente problemático en Isaías 50:4, donde el Siervo declara haber recibido ''lengua de sabios'' para saber sostener al cansado con una palabra oportuna. El significado ''ayudar'' o ''sostener'' es generalmente aceptado, aunque algunos eruditos lo consideran un aramaísmo emparentado con raíces arameas y árabes que significan socorrer. Otros sugieren corrupción textual y proponen enmiendas como ''responder'', ''enseñar'' o ''reanimar''. Pese a estas incertidumbres, el sentido fundamental de sustentar al fatigado con palabras oportunas encaja perfectamente con la misión del Siervo de consolar y fortalecer a los desalentados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5791', 'spa', 'Torcer, encorvar, pervertir; usado para distorsionar la justicia y para el encorvamiento físico de la vejez', 'En su sentido fundamental, este verbo significa torcer o deformar algo de su forma correcta. El Piel domina el uso, describiendo la distorsión moral de la justicia: «¿Acaso pervierte Dios el derecho?» (Job 8:3). Amós 8:5 lo aplica a la falsificación de las balanzas comerciales. El Pual pasivo en Eclesiastés 1:15 describe lo que ya está torcido más allá de toda corrección. De manera más evocadora, el Hitpael en Eclesiastés 12:3 retrata a los «hombres fuertes» del cuerpo encorvándose bajo el peso de la vejez: un volverse-torcido reflexivo que pasa de la metáfora moral a la realidad corporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5792', 'spa', 'agravio, injusticia, perversión de la justicia (privación del trato justo, especialmente de derechos legales)', 'Este sustantivo femenino significa agravio, injusticia o perversión de la justicia, refiriéndose específicamente a la tergiversación o negación de lo recto. En Lamentaciones 3, el hablante se lamenta de que Dios ha visto ''mi agravio'', empleando este término en paralelo con ''mi causa''. La palabra no denota simplemente un daño personal, sino la perversión o denegación de derechos legales, la distorsión de lo que debería ser recto. Proviene de una raíz que significa torcer o pervertir, capturando la idea de que la justicia ha sido deformada o los derechos de alguien han sido subvertidos. El hablante apela a Dios como juez supremo que ve cuando la justicia ha sido negada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5794', 'spa', 'Fuerte, poderoso, feroz; de personas, fuerzas o fortificaciones que poseen gran poder, severidad o audacia.', 'Fuerte, poderoso, feroz; de personas, fuerzas o fortificaciones que poseen gran poder, severidad o audacia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5795', 'spa', 'Cabra hembra; cabra(s) como ganado, alimento o sacrificio; también pelo de cabra usado como material textil para el tabernáculo.', 'Cabra hembra; cabra(s) como ganado, alimento o sacrificio; también pelo de cabra usado como material textil para el tabernáculo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5796', 'spa', 'cabras (forma plural aramea en la lista de ofrendas por el pecado en la dedicación del templo, Esdras)', 'Este sustantivo plural arameo significa ''cabras'', específicamente cabras hembras. Aparece en el relato de Esdras sobre la dedicación del templo reconstruido, donde los repatriados ofrecen sacrificios que incluyen toros, carneros, corderos y cabras como ofrenda por el pecado en representación de todo Israel. La forma aramea lo distingue del término hebreo más común para cabras, reflejando el contexto multilingüe del período postexílico en que el arameo era de uso generalizado. La ofrenda de cabras como sacrificio expiatorio sigue las prescripciones de la Torá. El número y la variedad de animales subrayan la importancia solemne de aquella dedicación del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5797', 'spa', 'Fuerza, poder, potencia — ya sea fortaleza física, majestad divina o la energía impetuosa de la autoridad y la alabanza.', 'Fuerza, poder, potencia — ya sea fortaleza física, majestad divina o la energía impetuosa de la autoridad y la alabanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5798a', 'spa', 'Uza o Uzá; nombre propio que significa ''fuerza'', llevado por varios personajes bíblicos.', 'El nombre Uza (o Uzá) deriva de la raíz עזז que significa ''ser fuerte'', y por tanto significa ''fuerza'' o ''mi fuerza''. El portador más memorable es el hombre que extendió su mano para sostener el Arca de la Alianza durante su traslado a Jerusalén y fue fulminado por Dios a causa de su presunción (2 Sam 6:3–8; 1 Cr 13:7–11), un acontecimiento tan impactante que David llamó al lugar Pérez-uza (''irrupción contra Uza''). El nombre también aparece como el jardín donde fueron sepultados los reyes Manasés y Amón (2 Re 21:18, 26), un benjaminita (1 Cr 8:7) y un jefe de familia entre los exiliados que regresaron (Esd 2:49; Neh 7:51).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5798b', 'spa', 'Uza (nombre propio que significa ''fuerza''; levita mencionado en las genealogías de Crónicas)', 'Uza es un nombre propio que significa ''fuerza'' y aparece en las genealogías levíticas de 1 Crónicas. El nombre deriva de la raíz que denota fuerza o poderío, la misma raíz que origina nombres como Uziel (''Dios es mi fuerza'') y Azarías (''YHWH ha ayudado''). Este Uza es distinto del más conocido Uza que tocó el arca y murió (2 Samuel 6), aunque ambos llevan el mismo nombre. Los nombres hebreos frecuentemente reflejaban convicciones o esperanzas teológicas: los padres que nombraban a un hijo Uza expresaban confianza en la fuerza, ya fuera vigor físico o el poder que proviene de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5799', 'spa', 'Azazel; nombre de lugar (remoción total) o espíritu/demonio del desierto en el ritual levítico de expiación', 'Azazel aparece exclusivamente en Levítico 16 en relación con el ritual del Día de la Expiación. Un macho cabrío se sacrifica a YHWH, mientras que otro es enviado «a Azazel» al desierto, llevando consigo los pecados de Israel. Las interpretaciones se dividen entre quienes ven a Azazel como un concepto abstracto (remoción completa, de la raíz עזל = remover) y quienes lo consideran un nombre propio de un espíritu o demonio del desierto, reflejado en la angelología judía posterior como un ángel caído. El ritual efectúa la eliminación total del pecado y la impureza del santuario y la comunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5800a', 'spa', 'Dejar, abandonar, desamparar; desde traición al pacto y partida física hasta el estado de abandono e incluso ayudar con una carga', 'El verbo azav es la palabra bíblica principal para el abandono y conlleva enorme peso teológico. Cuando Israel abandona al Señor (Jue 2:12-13), denuncia traición al pacto; cuando un hombre deja a su padre y a su madre (Gn 2:24), describe la partida natural que forma un nuevo hogar. Quizá lo más sorprendente sea el sentido raro de ''ayudar con una carga'' en Éxodo 23:5, donde el mismo verbo que en otros contextos significa ''abandonar'' se redirige hacia la ayuda compasiva, una inversión semántica que ha desconcertado a los lexicógrafos durante siglos. Las formas pasivas describen la devastadora condición de ser desamparado, estado que Isaías aplica tanto a ciudades desoladas como al propio pueblo de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5800b', 'spa', 'restaurar, reparar (significado incierto; posiblemente ''restauraron/fortificaron'', aunque podría derivar de ''abandonar'')', 'Este verbo aparece en el relato de Nehemías sobre la reconstrucción de los muros de Jerusalén y probablemente significa restaurar, reparar o posiblemente fortificar. El pasaje indica que los orfebres y perfumistas ''restauraron'' Jerusalén hasta el Muro Ancho. Sin embargo, el significado es debatido: el verbo podría derivar de una raíz que significa restaurar o erigir (cognada del sabeo), o bien de la raíz más común que significa ''abandonar'' o ''desamparar''. El peso de la evidencia favorece ''restauraron'' o ''fortificaron'', lo cual concuerda con el contexto del proyecto de reconstrucción de Nehemías, donde distintos grupos se encargaban de diferentes secciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5801', 'spa', 'Mercancías, productos comerciales; bienes intercambiados en el comercio, usado exclusivamente para la red comercial de Tiro en Ezequiel 27.', 'Sustantivo masculino que solo aparece en plural con sufijos, con el significado de ''mercancías'' o ''productos comerciales'': bienes que quedan en manos del comprador tras una transacción. Se encuentra exclusivamente en Ezequiel 27, el magnífico oráculo que cataloga el imperio comercial de Tiro. Sus socios comerciales le proveían hierro, estaño y plomo ''como tus mercancías'' (Ez 27:12), además de caballos, mulas, marfil, ébano, turquesas, coral, rubíes, trigo, miel, aceite y bálsamo. El término posiblemente deriva de עָזַב (''dejar''), sugiriendo bienes depositados o consignados en el comercio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5802', 'spa', 'Azbuc (nombre propio; padre de Nehemías, uno de los reconstructores del muro en la Jerusalén postexílica)', 'Azbuc es un nombre propio que aparece en el relato de la reconstrucción del muro de Nehemías. Se identifica como el padre de Nehemías (no el gobernador, sino otro hombre con el mismo nombre), quien gobernaba la mitad del distrito de Bet-sur y participó en la reparación de una sección del muro de Jerusalén. El significado del nombre es incierto, aunque podría contener elementos relacionados con fuerza o poder. Las diversas transliteraciones de la Septuaginta muestran los intentos de los traductores griegos por representar un nombre hebreo poco familiar. Azbuc aparece una sola vez en las Escrituras, conocido únicamente como padre de este gobernador de distrito que contribuyó a la reconstrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5803', 'spa', 'Azgad; nombre de un jefe de familia entre los exiliados que regresaron y firmante del pacto', 'Azgad (que significa «Gad es poderoso») es un nombre personal y de familia del período postexílico. Los «hijos de Azgad» regresaron de Babilonia con Zorobabel (Esdras 2:12 // Nehemías 7:17) y también con Esdras (Esdras 8:12). Un Azgad aparece igualmente entre quienes sellaron el pacto de Nehemías (Nehemías 10:15). El nombre refleja elementos teofóricos comunes en la onomástica israelita, invocando el nombre divino Gad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5804', 'spa', 'Gaza, la principal ciudad costera filistea; tambin Aya, un topnimo distinto en 1 Cr 7:28. Se refiere abrumadoramente a la famosa ciudad filistea en la', 'Gaza, la principal ciudad costera filistea; tambin Aya, un topnimo distinto en 1 Cr 7:28. Se refiere abrumadoramente a la famosa ciudad filistea en la costa meridional del Mediterrneo, la ms surena de las cinco grandes ciudades-estado filisteas. Aparece desde la Tabla de las Naciones (Gn 10:19) a travs de las narrativas de conquista y hasta los profetas, donde Ams pronuncia juicio contra ella por el trfico de esclavos (Am 1:6-7). El nombre aparece como ''Azzah'' en traducciones inglesas antiguas y ''Gaza'' en otras, ambas reflejando la misma forma hebrea. Una ocurrencia en 1 Cr 7:28 parece referirse a una localidad distinta, ''Aya'', segn confirma la evidencia multilinge.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5805', 'spa', 'lugar desolado, región abandonada (participio femenino usado como sustantivo: el lugar desamparado)', 'Este participio femenino funciona como sustantivo y significa ''el lugar desamparado'' o ''región desolada''. Aparece en la visión del llamado de Isaías, donde Dios advierte que el juicio producirá un gran abandono ''en medio de la tierra''. El término proviene de la raíz ''abandonar'' o ''desamparar'', y la forma participial enfatiza el estado de haber sido abandonado. La visión de Isaías anuncia que la tierra será vaciada de habitantes, quedando desolada y desierta. El artículo definido le otorga una cualidad concreta, casi personificada: no es mera desolación abstracta, sino un lugar específicamente abandonado donde antes había vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5806', 'spa', 'Azuba; nombre personal de dos mujeres: la madre de Josafat y la esposa de Caleb', 'Azuba (que significa «abandonada» o «desamparada») es el nombre de dos mujeres en el registro bíblico. La primera fue la madre del rey Josafat de Judá (1 Reyes 22:42 // 2 Crónicas 20:31). La segunda fue esposa de Caleb, mencionada en los registros genealógicos de Judá (1 Crónicas 2:18-19). A pesar de la connotación negativa del nombre, ambas mujeres ocuparon posiciones significativas en la genealogía israelita y en el linaje real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5807', 'spa', 'Fuerza, poder, fiereza; potencia vigorosa, ya sea en batalla o en actos divinos', 'Este sustantivo denota fuerza y poder formidable, esencialmente equivalente al más común עֹז. Isaías 42:25 lo usa para describir la «fiereza de la batalla» derramada por Yahvé sobre Israel rebelde, en paralelo con «el ardor de su ira». Salmo 145:6 celebra el «poder de tus hechos temibles», las obras estremecedoras de Dios a favor de su pueblo. Salmo 78:4 narra cómo se transmite a la siguiente generación la «fuerza y las maravillas» de Yahvé, las obras poderosas que definen la historia de Israel. El término enfatiza una fuerza vigorosa e intensa, a veces con connotaciones de violencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5809', 'spa', 'Nombre propio que significa ''socorrido'' o ''ayudador''; lo portan tres individuos, incluido el padre de un falso profeta', 'Azur, que significa «socorrido» o «ayudador», aparece como nombre de tres personas en las Escrituras. El más destacado es Azur, padre de Hananías, el falso profeta que se opuso a Jeremías en Jerusalén declarando que el yugo babilónico se quebraría en dos años, profecía que Jeremías condenó como mentira. Otro Azur aparece en Ezequiel 11:1 entre los líderes impíos que daban consejo perverso en Jerusalén. Un tercero fue uno de los principales del pueblo que sellaron la renovación del pacto de Nehemías. La ironía del nombre es notable: «Socorrido», pero asociado a falsa profecía y consejo inicuo, muestra que la ayuda humana sin la verdad divina conduce al extravío.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5810', 'spa', 'Ser fuerte, prevalecer; fortalecer; en Hifil, endurecer el rostro mostrando descaro o impudencia', 'Denota fuerza a lo largo de un espectro que va desde el poder físico hasta la audacia moral. Cuando la mano de Otoniel ''prevaleció contra'' Cusán-risataim (Jue 3:10) y el dominio de Madián ''se fortaleció contra'' Israel (Jue 6:2), el Qal expresa una fuerza física dominante. El Salmo 68:28 se convierte en una súplica para que Dios ''fortalezca'' lo que ha hecho. El Hifil introduce un matiz ético: Proverbios 21:29 dice que el impío ''endurece su rostro'' en descarada rebeldía, mientras que Proverbios 7:13 describe a la mujer adúltera que ''endureció su rostro''. Así, el término abarca desde la supremacía en el campo de batalla hasta la impudencia moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5811', 'spa', 'Azaz (nombre propio; rubenita mencionado en las genealogías de Crónicas)', 'Azaz es un nombre propio que aparece en las genealogías de Rubén en 1 Crónicas. El nombre podría derivar de una raíz que significa ''ser fuerte'' o ''poderoso'', quizá como forma abreviada de un nombre teofórico más largo, o bien de una raíz que significa ''refugiarse''. Los nombres hebreos frecuentemente celebraban la fuerza, ya fuera el poder físico o la fortaleza hallada en Dios. Azaz aparece una sola vez en las Escrituras, preservado en los registros tribales de Rubén, el primogénito de Jacob que perdió su primogenitura. Representa a uno de los innumerables israelitas cuyos nombres fueron conservados en los registros genealógicos que sustentaban la identidad tribal de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5812', 'spa', 'Nombre propio que significa ''Yahvé es poderoso''; levitas y un benjaminita en Crónicas', 'Azazías, que significa «Yahvé es poderoso», es el nombre de varios individuos en Crónicas, aunque algunas apariciones presentan cuestiones textuales. El nombre es esencialmente equivalente a Uzías/Azarías, formas variadas de la misma construcción teofórica que afirma la fuerza de Yahvé. Uno de los Azazías fue un músico levita designado para tocar la lira durante el traslado del arca bajo David. Otro aparece entre los funcionarios administrativos de Ezequías que supervisaban las ofrendas del templo. Un líder benjaminita también llevó este nombre. La Septuaginta suele traducirlo como Ozías, mostrando las convenciones ortográficas variables para nombres teofóricos en la transmisión antigua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5813', 'spa', 'Uzzi — ''mi fuerza'', nombre propio de varios sacerdotes y líderes tribales en Crónicas-Esdras-Nehemías', 'El nombre עֻזִּי (Uzzi), que significa ''mi fuerza'' (de la raíz עזז, ''ser fuerte''), pertenece a al menos seis individuos distintos en el Antiguo Testamento, todos ellos presentes en listas genealógicas y administrativas. El más destacado es un descendiente de Aarón por la línea de Eleazar y Finees en el linaje sumo sacerdotal (1 Cr 6:5-6, 51; Esd 7:4). Otros incluyen un jefe de clan de Isacar (1 Cr 7:2-3), un benjaminita (1 Cr 7:7; 9:8), un supervisor levítico en la Jerusalén postexílica (Neh 11:22) y figuras sacerdotales en las listas de Nehemías (Neh 12:19, 42). El nombre refleja la práctica israelita de incorporar lenguaje teofórico de fuerza en los nombres personales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5814', 'spa', 'Uzías (nombre propio que significa ''YHWH es mi fortaleza''; uno de los valientes de David)', 'Uzías es un nombre propio que significa ''YHWH es mi fortaleza'', compuesto por ''uzzi'' (mi fortaleza) y ''Yah'' (forma abreviada de YHWH). Este Uzías en particular fue uno de los valientes de David, los guerreros de élite que lo apoyaron durante su reinado. Se distingue del más conocido rey Uzías de Judá, aunque ambos comparten el mismo nombre teofórico que celebra a Dios como fuente de fortaleza. Los nombres que incorporaban ''uzzi'' eran comunes en el antiguo Israel, reflejando la dependencia del pueblo en el poder divino antes que en la fuerza humana. Este guerrero Uzías aparece únicamente en la lista de los héroes de David en 1 Crónicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5815', 'spa', 'Aziel (nombre propio; músico levita, probablemente variante textual de Uziel)', 'Aziel es un nombre propio que aparece en el relato del traslado del arca a Jerusalén por parte de David. Fue un músico levita designado para tocar liras. Sin embargo, los estudiosos reconocen ampliamente que Aziel es probablemente un error de copista o una forma abreviada de Uziel, ya que el versículo 20 lo llama Aziel mientras que el versículo 18 lo llama Uziel. El nombre Uziel significa «Dios es mi fortaleza». Tales variaciones textuales son comunes en las listas genealógicas y litúrgicas de Crónicas, y reflejan la compleja historia de transmisión de estos textos. Ya sea como Aziel o Uziel, formó parte de los músicos que celebraron la llegada del arca con alabanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5816', 'spa', 'Uziel -- nombre propio que significa ''mi fortaleza es Dios'', llevado por levitas, un simeonita y un benjaminita. Nombre teofrico compuesto de uzzî (''m', 'Uziel -- nombre propio que significa ''mi fortaleza es Dios'', llevado por levitas, un simeonita y un benjaminita. Nombre teofrico compuesto de uzzî (''mi fortaleza'') y ''ēl (''Dios''). Uziel aparece ms prominentemente como hijo de Coat y nieto de Lev, convirtindose en el antepasado epnimo del clan levtico uzielita (x 6:18, 22; Lv 10:4; Nm 3:19, 30; 1 Cr 6:3; 15:10; 23:12, 20; 24:24). Sus descendientes Misael y Elzafn sacaron los cuerpos de Nadab y Abi del santuario (Lv 10:4). Otros portadores incluyen un msico levita (1 Cr 25:4), un levita de la poca de Ezequas (2 Cr 29:14), un lder militar simeonita (1 Cr 4:42), un benjaminita (1 Cr 7:7) y un reparador de muros bajo Nehemas (Neh 3:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5818', 'spa', 'Uzías (''mi fuerza es Yah''), principalmente el rey de Judá (c. 792-740 a.C.), nombre compartido por varios levitas y funcionarios.', 'Uzías (''mi fuerza es Yah''), principalmente el rey de Judá (c. 792-740 a.C.), nombre compartido por varios levitas y funcionarios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5819', 'spa', 'Aziza (nombre propio; israelita que se divorció de su esposa extranjera durante las reformas de Esdras)', 'Aziza es un nombre propio que aparece en la lista de Esdras de los hombres que se habían casado con mujeres extranjeras y aceptaron divorciarse durante las reformas postexílicas. El nombre posiblemente significa «fuerte» o «poderoso», derivado de la raíz que denota fortaleza. Pertenecía a los descendientes de Zatú que habían contraído matrimonios mixtos, lo cual Esdras consideraba una amenaza para la fidelidad del pacto comunitario. Su inclusión en la lista indica que acató la exigencia de Esdras de repudiar a su esposa extranjera, una decisión personalmente costosa tomada en aras de la santidad colectiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5820', 'spa', 'Azmavet, nombre propio que significa ''la muerte es fuerte'', llevado por varios hombres del círculo de David y un benjaminita.', 'Sustantivo propio masculino cuyos componentes — עֹז (fuerza) y מָוֶת (muerte) — sugieren ''la muerte es fuerte'' o ''fuerte hasta la muerte''. Lo llevan varios individuos distintos: uno de los treinta valientes de David (2 S 23:31, 1 Cr 11:33), el padre de dos combatientes benjaminitas que se unieron a David en Siclag (1 Cr 12:3), un tesorero real bajo David (1 Cr 27:25), y un benjaminita en la genealogía de Saúl (1 Cr 8:36, 9:42). También aparece como topónimo para una ciudad repoblada tras el exilio (Esd 2:24, Neh 12:29). La Septuaginta generalmente lo traduce como Azmoth o Asmoth.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5821', 'spa', 'Azán (nombre propio; padre de Paltiel, líder de Isacar durante el período del desierto)', 'Azán es un nombre propio que significa quizás «fuerte» o «agudo», y aparece en Números como el padre de Paltiel, quien representó a la tribu de Isacar en la distribución de la Tierra Prometida. El nombre podría derivar de una raíz relacionada con la fortaleza o de otra que significa aguzar o afilar. Su hijo Paltiel fue elegido como uno de los líderes tribales encargados de supervisar la asignación de Canaán entre las tribus, tarea crucial que requería hombres de confianza para garantizar un reparto justo. Azán es conocido únicamente a través del papel de su hijo en esta importante labor administrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5823', 'spa', 'Cavar alrededor, labrar cuidadosamente (Piel intensivo: trabajar la tierra a fondo alrededor de las plantas)', 'Este verbo en forma Piel significa cavar alrededor o labrar cuidadosamente, especialmente el cultivo minucioso del suelo alrededor de las plantas. La forma intensiva Piel sugiere un trabajo meticuloso y esmerado. En el Cántico de la Viña de Isaías, el amado prepara su viña cavando y labrando la tierra con esmero, quitando piedras y plantando cepas escogidas; cada detalle muestra un cuidado intensivo. El verbo se relaciona con raíces árabes y etiópicas que significan hendir o surcar la tierra con una herramienta. La imagen es la de un viñador que no escatima esfuerzo en preparar el suelo, haciendo que el fracaso de la viña en producir buenas uvas resulte aún más trágico e inexcusable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5825', 'spa', 'Azeca, ciudad fortificada en la Sefelá de Judá cerca de Soco, asociada con batallas contra cananeos y filisteos.', 'Azeca fue una ciudad fortificada de importancia estratégica en las tierras bajas (Sefelá) de Judá, cerca de Soco. Aparece en algunas de las narrativas militares más dramáticas de las Escrituras: la persecución israelita de la coalición amorrea bajo granizo (Jos 10:10-11), el valle donde David enfrentó a Goliat (1 S 17:1), y como una de las dos últimas fortalezas de Judá que aún resistían a Nabucodonosor (Jer 34:7). Roboam la fortificó como parte de su sistema defensivo. Las traducciones en distintos idiomas transliteran el nombre de forma consistente, reflejando su firme identidad como topónimo en todas las tradiciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5826', 'spa', 'Ayudar, asistir, socorrer; como participio, un ayudador o aliado; en Nifal, ser ayudado; en Hifil, prestar ayuda.', 'Ayudar, asistir, socorrer; como participio, un ayudador o aliado; en Nifal, ser ayudado; en Hifil, prestar ayuda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5827', 'spa', 'Ezer (nombre propio que significa «ayuda»; efrateo mencionado en las genealogías de Crónicas)', 'Ezer es un nombre propio que significa «ayuda» o «auxiliador», derivado de la raíz que denota ayudar o sostener. Este Ezer en particular fue un efrateo mencionado en las genealogías de 1 Crónicas, muerto por hombres de Gat cuando él y sus hermanos bajaron a robar su ganado. El nombre refleja un patrón hebreo común de celebrar la ayuda, ya sea humana o divina. Nombres afines como Ebenezer («piedra de ayuda») y Eleazar («Dios es ayuda») muestran la importancia de este tema en la onomástica israelita. La trágica historia de este Ezer —muerto en una incursión fallida por ganado— muestra que incluso alguien llamado «ayuda» podía morir joven. Su padre Efraín lo lloró durante muchos días.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5828', 'spa', 'Ayuda, auxilio, socorro; también concretamente un ayudador o quien presta asistencia, especialmente como epíteto divino.', 'Ayuda, auxilio, socorro; también concretamente un ayudador o quien presta asistencia, especialmente como epíteto divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5829', 'spa', 'Ézer; nombre personal de tres individuos: un judahíta, un guerrero gadita y un constructor de muros', 'Ézer (que significa «ayuda» o «ayudador») es un nombre hebreo común que llevaron al menos tres personas en las Escrituras. Uno fue descendiente de Judá, padre de Husá (1 Crónicas 4:4). Otro fue un guerrero gadita que se unió a David en Siclag (1 Crónicas 12:9). El tercero fue un sacerdote que participó en la ceremonia de dedicación del muro de Nehemías (Nehemías 12:42), posiblemente el mismo constructor mencionado en Nehemías 3:19. El nombre refleja confianza en la ayuda divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5830', 'spa', 'Esdras — el sacerdote y escriba que lideró el retorno postexílico y restauró la observancia de la Torá en Jerusalén.', 'Esdras — el sacerdote y escriba que lideró el retorno postexílico y restauró la observancia de la Torá en Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5831', 'spa', 'Esdras; nombre del escriba y sacerdote que lideró la reforma postexílica, mencionado aquí en las secciones arameas', 'Estas tres apariciones se encuentran en las porciones arameas de Esdras 7, donde el decreto de Artajerjes comisiona a Esdras, sacerdote y escriba, para liderar el segundo gran retorno a Jerusalén. El nombre «Esdras» (que significa «ayuda») aparece en la correspondencia imperial persa oficial que lo autoriza a enseñar la ley, nombrar jueces y administrar justicia conforme a «la ley de tu Dios y la ley del rey». Las secciones arameas preservan la documentación administrativa del apoyo persa a la comunidad restaurada, otorgando a Esdras una autoridad extraordinaria para restaurar la observancia de la Torá entre los exiliados que habían regresado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5832', 'spa', 'Azarel (''Dios ha ayudado''), nombre propio de seis individuos: un guerrero de David, un músico levita, un jefe danita y otros.', 'Azarel (עֲזַרְאֵל, ''El ha ayudado'') es un nombre teofórico que combina la raíz עזר (''ayudar'') con el elemento divino אֵל. Designa al menos a cinco hombres distintos: un guerrero benjaminita que se unió a David en Siclag (1 Cr 12:7), un músico levita designado por sorteo (1 Cr 25:18, posiblemente idéntico a Uziel en v. 4), un jefe tribal danita (1 Cr 27:22), un hombre que había tomado esposa extranjera bajo la reforma de Esdras (Esd 10:41), y una o dos figuras sacerdotales en la época de Nehemías (Neh 11:13; 12:36). La popularidad del nombre a lo largo de tribus y períodos refleja la profunda confianza de Israel en la ayuda divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5833', 'spa', 'Ayuda, socorro, auxilio — especialmente la asistencia divina en la batalla o la angustia; también ayuda concreta y encarnada de un aliado.', 'Ayuda, socorro, auxilio — especialmente la asistencia divina en la batalla o la angustia; también ayuda concreta y encarnada de un aliado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5834', 'spa', 'Ezrá (nombre propio; miembro de la tribu de Judá en las genealogías de Crónicas)', 'Ezrá es un nombre propio que aparece en las genealogías de Judá en 1 Crónicas. El nombre probablemente significa «ayuda» y está relacionado con la raíz hebrea que denota auxilio, similar a Ézer y Esdras. Este Ezrá figura entre los descendientes de Judá, dentro de los complejos registros genealógicos que establecían la identidad tribal y los derechos sobre la tierra. Aparece únicamente en este contexto genealógico, como uno de muchos judahitas cuyos nombres fueron preservados en los registros tribales. Las genealogías hebreas cumplían funciones esenciales: establecían identidad, derechos de herencia y conexión con la comunidad del pacto, otorgando significado incluso a una sola mención.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5835', 'spa', 'Cornisa o repisa del altar; atrio o recinto cerrado del templo', 'Término arquitectónico con dos aplicaciones relacionadas pero distintas en contextos del templo. En la visión del altar ideal de Ezequiel (Ez 43:14-20; 45:19), עֲזָרָה designa la cornisa o repisa horizontal que sobresale de la base del altar. En 2 Crónicas (4:9; 6:13), la misma palabra se refiere al gran atrio cerrado del templo de Salomón. Ambas acepciones comparten la idea raíz de un área delimitada y consagrada que rodea una estructura sagrada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5836', 'spa', 'Ezri (nombre propio que significa «mi ayuda»; oficial agrícola de David sobre los trabajadores del campo)', 'Ezri es un nombre propio que significa «mi ayuda», formado al añadir el sufijo posesivo de primera persona a la raíz hebrea que denota auxilio. Este Ezri sirvió en la administración de David como oficial encargado de los trabajadores del campo, esencialmente el ministro de agricultura del reino. El nombre celebra la ayuda personal, posiblemente divina. El gobierno de David incluía cargos administrativos detallados que gestionaban asuntos militares, religiosos, agrícolas y financieros. El papel de Ezri supervisando a los labradores demuestra la importancia de la agricultura para la economía del reino y la necesidad de una gestión organizada de las tierras reales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5837', 'spa', 'Nombre propio que significa ''mi ayuda es Dios''; tres individuos, incluido un perseguidor de Jeremías', 'Azriel, que significa ''mi ayuda es Dios'', es el nombre de tres hombres en las Escrituras. El más memorable fue uno de los tres enviados por el rey Joacim para arrestar a Jeremías y a Baruc tras la lectura y quema del rollo profético, misión que fracasó porque Yahvé los escondió. Otro Azriel fue un jefe guerrero de la media tribu de Manasés, y un tercero aparece en los registros administrativos de Neftalí durante el reinado de David. El elemento teofórico del nombre afirma a Dios como ayudador, aunque la conducta de sus portadores no siempre corresponde al significado piadoso del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5838', 'spa', 'Azarías (''Yah ha ayudado''); nombre propio llevado por reyes, sacerdotes y oficiales en Judá.', 'Azarías (''Yah ha ayudado''); nombre propio llevado por reyes, sacerdotes y oficiales en Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5839', 'spa', 'Azarías (nombre propio que significa «YHWH ha ayudado»; compañero de Daniel en el exilio babilónico)', 'Azarías es un nombre propio que significa «YHWH ha ayudado», combinando el nombre divino con un verbo que denota auxilio. Este Azarías fue uno de los tres compañeros de Daniel en el exilio babilónico, más conocido por su nombre babilónico Abednego. Los babilonios les asignaron nuevos nombres para asimilarlos: Daniel pasó a ser Beltsasar, Hananías se convirtió en Sadrac, Misael en Mesac y Azarías en Abednego. La ironía es profunda: su nombre hebreo proclamaba «YHWH ha ayudado», una confesión de fe en el Dios de Israel, pero en Babilonia fue renombrado en honor a una deidad pagana. Pese a ello, Azarías permaneció fiel, rehusando adorar la imagen de oro de Nabucodonosor y sobreviviendo al horno de fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5840', 'spa', 'Azricam (''mi ayuda se ha levantado''), nombre propio de un descendiente davídico, un benjaminita, un levita y un oficial de palacio.', 'Azricam (עַזְרִיקָם, ''mi ayuda se ha levantado'') es un nombre compuesto formado por עֶזְרִי (''mi ayuda'') y קָם (''se ha levantado''). Identifica a cuatro individuos distintos: un descendiente del rey David por la línea de Nearías (1 Cr 3:23), un benjaminita en la genealogía de Saúl (1 Cr 8:38; 9:44), un portero levita (1 Cr 9:14; Neh 11:15) y un alto funcionario de la casa del rey Acaz, a quien el guerrero efraimita Zicri mató durante la invasión de Pecaj (2 Cr 28:7). La Septuaginta lo traduce como Ezreikan o Ezrikam en estos contextos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5842', 'spa', 'Estilo, pluma; instrumento de escritura hecho de hierro (para piedra/metal) o de caña (para rollos)', 'Este sustantivo designa un instrumento de escritura cuyo material y uso varían según el contexto. Jeremías 17:1 y Job 19:24 describen un estilo de hierro con punta de diamante para grabar inscripciones permanentes en piedra o metal. Jeremías 8:8 y Salmo 45:1 se refieren a una pluma de caña usada por escribas para escribir en rollos. Este último pasaje declara bellamente: «Mi lengua es pluma de escribiente muy diestro», empleando la imagen de la escritura fluida para describir un discurso elocuente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5843', 'spa', 'consejo, dictamen, juicio (sustantivo arameo para consejo sabio o decisión prudente)', 'Este sustantivo arameo significa consejo, dictamen o juicio, es decir, el resultado de una deliberación sabia. Aparece en Daniel cuando Arioc, comandante de la guardia real, viene a ejecutar a los sabios por no interpretar el sueño de Nabucodonosor. Daniel le pregunta a Arioc sobre la «urgencia del decreto», indagando acerca de la severa decisión del rey con un término que abarca tanto «consejo» como «decreto». La palabra está relacionada con la raíz aramea que significa gustar y, por extensión, juzgar o discernir. La literatura sapiencial asocia frecuentemente el gustar con la discriminación y el juicio: se prueba algo para determinar su naturaleza. Aquí describe la decisión del rey de ejecutar a todos los sabios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5844a', 'spa', 'Envolverse o cubrirse con una prenda; cubrir a otro (transitivo); en causativo, vestir o arropar.', 'El verbo עטה evoca la acción de envolver una prenda alrededor del cuerpo: cubrirse el rostro con un manto, drapearse con una capa o cubrirse la cabeza en señal de duelo. En el Qal reflexivo, el espectro de Samuel asciende ''envuelto en un manto'' (1 Sam 28:14), y Dios ''se envuelve de luz como con vestidura'' (Sal 104:2). El Qal transitivo se extiende a cubrir a otros: los leprosos deben cubrirse el labio superior (Lev 13:45). El Hifil intensifica la agencia, describiendo a Dios cubriendo a alguien de vergüenza (Sal 89:45).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5845', 'spa', 'baldes, cubos (recipientes para contener leche o líquido, usados en la metáfora de prosperidad de Job)', 'Este sustantivo masculino plural significa baldes, cubos o recipientes para contener líquidos. El término aparece en la descripción que hace Job de alguien que muere en plena prosperidad: «sus baldes están llenos de leche», es decir, sus recipientes rebosan de abundancia. La imagen evoca salud robusta y bendición material: alguien cuya producción lechera es tan abundante que hasta los recipientes de almacenamiento desbordan. Relacionado con la palabra del hebreo tardío para un recipiente de aceitunas, describe vasijas agrícolas usadas para leche u otros productos. La metáfora contrasta fuertemente con otra persona que muere en amargura sin haber gozado de prosperidad, resaltando las desigualdades de la vida que desconciertan a Job y a sus amigos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5846', 'spa', 'estornudos (sustantivo plural femenino que designa las exhalaciones nasales explosivas del Leviatán en Job)', 'Este sustantivo plural femenino significa estornudos, las exhalaciones explosivas por la nariz. Aparece en la magnífica descripción del Leviatán en Job, la temible criatura marina: «sus estornudos lanzan destellos de luz», creando la imagen de una respiración tan poderosa que incluso la bruma de sus fosas nasales resplandece espectacularmente. El plural puede enfatizar la naturaleza repetida o dramática del aliento de la criatura. El término es exclusivo de este pasaje, parte de la elaborada descripción poética del poder aterrador del Leviatán, donde hasta su estornudo produce luz, sugiriendo fuego o el reflejo del sol sobre el agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5847', 'spa', 'Murciélago; mamífero volador clasificado como inmundo en la ley levítica', 'El murciélago aparece en las listas bíblicas de criaturas inmundas, prohibido como alimento bajo la ley levítica. Tanto Levítico 11:19 como Deuteronomio 14:18 lo incluyen entre las aves, ya que la taxonomía antigua agrupaba a los seres voladores sin distinguir entre aves y mamíferos. La forma es cuadriliteral, posiblemente emparentada con términos fenicios y norteafricanos. De modo impactante, Isaías 2:20 anuncia un día en que los hombres arrojarán sus ídolos «a los topos y a los murciélagos», criaturas de oscuridad y lugares ocultos, sugiriendo la total inutilidad de los ídolos, dignos solo de ser abandonados en las cuevas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5848a', 'spa', 'volverse, apartarse (cambiar de dirección, indicando incapacidad de ver o encontrar)', 'Este verbo en Qal imperfecto significa volverse, apartarse o cambiar de dirección. La raíz se relaciona con palabras siríacas y árabes para girar, inclinar o doblar. En el lamento de Job sobre la inaccesibilidad de Dios, dice que cuando Dios actúa a la derecha, «se vuelve a la izquierda y no lo percibo». El sentido es de buscar sin encontrar, de un Dios que permanece esquivo pese a la búsqueda incesante de Job. Ya sea que Dios se aparta o que Job se vuelve para mirar, el resultado es el mismo: Dios permanece oculto. El verbo capta la frustración de buscar la presencia divina y encontrar solo ausencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5848c', 'spa', 'Desfallecer, desmayarse o debilitarse; por agotamiento físico, abrumamiento emocional o desesperación espiritual.', 'Un verbo que da voz a la experiencia de sentirse abrumado hasta el punto del colapso. Los salmistas recurren a él cuando el espíritu desfallece: ''cuando mi corazón desmaya, llévame a la roca'' (Sal 61:2). Aparece en Lamentaciones cuando los lactantes se desmayan en las calles, y en Génesis para las ovejas débiles del rebaño de Labán. El Hitpael reflexivo, que domina el uso, intensifica la cualidad íntima y personal del desfallecimiento, presentándolo como una experiencia interior en la que las fuerzas se van drenando.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5849b', 'spa', 'Coronar, adornar con corona; de Dios coronando con gloria, honra o misericordia', 'Verbo denominativo derivado de עֲטָרָה (''corona''), usado en el Piel con el sentido de ''coronar'' o ''ceñir de honra''. Su uso más célebre se encuentra en el Salmo 8:5, donde Dios corona al ser humano de gloria y majestad. El Salmo 103:4 describe a Dios coronando al fiel con misericordia y compasión, mientras que el Salmo 65:11 presenta el año coronado con la bondad divina. Cantares 3:11 recuerda a la madre de Salomón coronándolo el día de su boda. Isaías 23:8 aplica la imagen a Tiro como la que otorgaba coronas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5850', 'spa', 'Corona, guirnalda — un aro de realeza, honor o bendición, tanto tocado literal como emblema figurado de dignidad.', 'Corona, guirnalda — un aro de realeza, honor o bendición, tanto tocado literal como emblema figurado de dignidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5851', 'spa', 'Atará (nombre propio femenino que significa ''corona'' o ''guirnalda''; mujer en la genealogía de Judá)', 'Atará es un nombre propio femenino que significa «corona», «guirnalda» o «diadema», derivado de la raíz que indica coronar o adornar. Esta Atará fue esposa de Jerameel, de la tribu de Judá, mencionada en las genealogías de 1 Crónicas como madre de Onam, dentro de la rama jerameelita. El nombre evoca belleza y honor, pues las coronas simbolizaban realeza, victoria y celebración en el antiguo Israel. Nombrar así a una hija expresaba la esperanza de dignidad y honra. Atará representa a las muchas mujeres que aparecen brevemente en las genealogías, cuya mención principal es como esposas y madres a través de quienes continuaban los linajes tribales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5852', 'spa', 'Atarot; nombre de varias localidades, principalmente en Transjordania (Gad) y Canaán central (Efraín/Benjamín)', 'Atarot (que significa «coronas» o «guirnaldas») es el nombre de varias ciudades en el Israel bíblico. La más destacada se encuentra al este del Jordán, construida por Gad (Números 32:3, 34), y también mencionada en la Estela de Mesa. Otra variante, Atarot-sofán, aparece en Números 32:35. Al oeste del Jordán, Atarot marca los límites entre Efraín y Benjamín (Josué 16:2, 5, 7; 18:13). Una tercera, Atarot-bet-joab, aparece en las genealogías de Judá (1 Crónicas 2:54). El nombre probablemente deriva de la topografía o las fortificaciones locales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5855', 'spa', 'Atrot-sofán (topónimo que significa ''coronas de Sofán''; ciudad transjordana edificada por los gaditas)', 'Atrot-sofán es un topónimo que posiblemente significa «coronas de Sofán» o «Atarot de Sofán», identificando una Atarot específica (nombre común de lugar que significa «coronas» o «guirnaldas») mediante un elemento distintivo. Situada al este del Jordán, fue una de las ciudades que la tribu de Gad reconstruyó o fortificó tras la conquista. El texto la distingue de otras ciudades también llamadas Atarot tanto en Transjordania como en Cisjordania. Su ubicación exacta es desconocida, aunque estaba en el territorio asignado a Gad. El plural «coronas» podría referirse a cimas de colinas o fortificaciones circulares, dado que los lugares a menudo recibían nombres según rasgos geográficos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5856', 'spa', 'ruina, montón de escombros; restos físicos tras la destrucción de una ciudad o edificación', 'Este término designa los restos materiales que quedan después de una destrucción violenta: montones de piedras y escombros donde antes se alzaban ciudades o edificios. Aparece en juicios proféticos contra Jerusalén y Samaria, donde Dios advierte que estas ciudades serán reducidas a montones de piedras. La forma plural de influencia aramea se encuentra en los oráculos de Miqueas, mientras que Jeremías cita la profecía de Miqueas sobre la reducción de Jerusalén a ruinas. El sentido concreto apunta siempre a estructuras demolidas tras una conquista militar o un juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5857', 'spa', 'Hai -- la antigua ciudad cananea cerca de Betel, destruida por Josue; tambien la variante Aja en listas postexilicas', 'Hai -- la antigua ciudad cananea cerca de Betel, destruida por Josue; tambien la variante Aja en listas postexilicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5858a', 'spa', 'Ebal (nombre gentilicio; pueblo árabe descendiente de Joctán en la Tabla de las Naciones)', 'Ebal es un nombre que aparece en la Tabla de las Naciones como uno de los hijos de Joctán, representando un pueblo árabe. Los descendientes de Joctán se asentaron en el sur de Arabia, y Ebal figuraba entre estas tribus árabes. El nombre aparece en dos formas en el texto bíblico: Obal en Génesis y Ebal en Crónicas, probablemente designando al mismo grupo con variantes ortográficas. La identificación geográfica precisa de los descendientes de Joctán es difícil, aunque los estudiosos han propuesto conexiones con diversas regiones de Arabia. La Tabla de las Naciones en Génesis 10 organiza el mundo conocido de forma etnográfica, mostrando las relaciones entre los pueblos mediante la ancestría común, con los árabes joctanitas como una rama significativa de los descendientes de Sem.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5858c', 'spa', 'Ebal — monte de la maldición al norte de Siquem, frente al monte Gerizim', 'El monte Ebal se alza al norte de Siquem (la actual Nablus), frente al monte Gerizim hacia el sur. En Deuteronomio 11:29 y 27:4, 13 queda designado como el monte desde el cual se pronuncian las maldiciones del pacto, mientras que Gerizim acoge las bendiciones. Josué 8:30 registra que Josué edificó un altar en Ebal tras la conquista de Hai. La etimología del nombre permanece incierta, aunque algunos la han vinculado a una raíz que significa ''desnudo'' o ''pedregoso''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5859', 'spa', 'Ijón/Iyón; ciudad de Neftalí repetidamente conquistada durante el período del reino dividido de Israel', 'Ijón fue una ciudad estratégica en el norte de Neftalí que sufrió invasiones repetidas durante la época del reino dividido. Ben-adad de Siria la atacó como parte de su alianza con Asá de Judá contra Baasa de Israel. Décadas después, Tiglat-pileser III de Asiria la conquistó durante su campaña contra Pécaj, deportando a sus habitantes. Su ubicación en la meseta de Merj Iyún, entre dos afluentes del alto Jordán, la hacía estratégicamente valiosa pero vulnerable. Los estudiosos la identifican con Tell Dibbin, aunque su localización exacta sigue siendo debatida. Las conquistas sucesivas ilustran la exposición del norte de Israel a las potencias extranjeras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5860', 'spa', 'abalanzarse sobre, lanzarse vorazmente sobre algo (describiendo soldados que se arrojan con avidez sobre el botín)', 'Este verbo significa abalanzarse, arrojarse o lanzarse con voracidad sobre algo, como un ave de rapiña que se precipita sobre su presa. Aparece en el relato del juramento imprudente de Saúl, que prohibió a su ejército comer durante la batalla. Tras la derrota de los filisteos, el pueblo, extenuado por el ayuno forzado durante toda la jornada, ''se abalanzó sobre el botín'' con desesperación: tomaron ovejas, ganado y terneros, degollándolos en el suelo y comiendo la carne con la sangre, en violación de la Torá. El verbo captura la hambre feroz e incontrolable que impulsó esta acción violenta y desenfrenada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5860a', 'spa', 'increpar a gritos, vociferar contra, insultar con violencia verbal (describiendo un ataque verbal áspero y agresivo)', 'Este verbo significa increpar a gritos, vociferar contra alguien o agredirlo verbalmente con dureza. La raíz se relaciona con palabras árabes que significan gritar, reprender e injuriar, y con términos siríacos para expresar ira. En 1 Samuel, describe la reacción de Nabal cuando los hombres de David le pidieron provisiones. Aunque estos habían protegido a los pastores y rebaños de Nabal en el desierto, él ''los increpó a gritos'', respondiendo con insultos y negándose a reconocer a David. El verbo captura la respuesta grosera y abusiva de Nabal: no se limitó a rehusar, sino que lo hizo con un asalto verbal. Su nombre significa ''necio'', y su conducta lo confirmó plenamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5860b', 'spa', 'abalanzarse sobre, apoderarse con avidez (describiendo la apropiación codiciosa del botín amalecita por parte de Saúl)', 'Este verbo denominativo significa lanzarse con codicia o abalanzarse sobre algo, como un ave rapaz que se precipita sobre su presa. Aparece en la reprensión de Samuel a Saúl tras la campaña contra los amalecitas. Dios había ordenado la destrucción total de los amalecitas y sus posesiones, pero Saúl perdonó al rey Agag y conservó el mejor ganado. Samuel lo confronta: ''¿Por qué no obedeciste la voz de YHWH? ¿Por qué te abalanzaste sobre el botín e hiciste lo malo ante los ojos de YHWH?'' El verbo sugiere una apropiación rapaz y codiciosa de lo prohibido. La excusa de Saúl de guardar los animales para sacrificar a Dios no satisfizo a Samuel, quien declaró que la obediencia vale más que los sacrificios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5861', 'spa', 'Ave de rapiña o rapaz; usado colectivamente para aves carroñeras e individualmente como metáfora de un invasor veloz y feroz.', 'Sustantivo masculino que designa un ave de rapiña, derivado de una raíz que sugiere un grito estridente. Aparece tanto como término colectivo para rapaces que descienden sobre cadáveres — como en la escena del pacto donde Abram ahuyenta las aves de rapiña de su sacrificio (Gn 15:11) — como figura singular que representa a un poderoso invasor convocado por Dios (Is 46:11, ''un ave de rapiña del oriente''). Jeremías 12:9 lo emplea en una llamativa doble imagen de Israel como ave depredadora y presa. El término también evoca rapaces que se alimentan tras matanzas escatológicas (Is 18:6, Ez 39:4). Job 28:7 señala que ni el ojo agudo de la rapaz puede hallar el camino hacia la sabiduría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5862', 'spa', 'Etam — topónimo: un peñasco en Judá, una ciudad cerca de Belén y una localidad de Simeón', 'Etam aparece como nombre de lugar en tres contextos distintos. Primero, es la peña rocosa donde Sansón se refugió después de atacar a los filisteos (Jue 15:8, 11). Segundo, es una ciudad fortificada por Roboam entre Belén y Tecoa (2 Cr 11:6), vinculada al clan registrado en 1 Crónicas 4:3. Tercero, podría tratarse de un asentamiento simeonita (1 Cr 4:32). El nombre posiblemente derive de una palabra que significa ''ave de rapiña'', aunque esto es incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5865', 'spa', 'para siempre, perpetuidad, eternidad (larga duración pasada o futura, posible variante textual en 2 Crónicas)', 'Esta palabra significa para siempre, perpetuidad, larga duración o eternidad. Es uno de los términos temporales más importantes del hebreo, y se refiere a una duración indefinidamente extensa, ya sea hacia el pasado (tiempos antiguos, desde antaño) o hacia el futuro (para siempre, eternamente). Aparece a lo largo de las Escrituras en expresiones como ''por los siglos de los siglos'' y ''desde la eternidad hasta la eternidad''. En 2 Crónicas 33:7 se presenta una forma inusual que podría ser una variante ortográfica o un problema textual donde Manasés coloca un ídolo en el templo ''para siempre''. El sentido fundamental es duración que excede todo cómputo humano, adecuado para describir la naturaleza eterna de Dios y Su pacto perpetuo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5866', 'spa', 'Ilai (nombre propio; uno de los valientes guerreros de David, del clan ahohíta)', 'Ilai es un nombre propio que aparece en la lista de los valientes guerreros de David. Se le identifica como ahohíta, perteneciente a un clan benjaminita que produjo varios de los combatientes de élite de David. El pasaje paralelo en 2 Samuel 23:28 lo llama Zalmón, lo que sugiere que Ilai era un nombre alterno o que existe una variante textual entre ambos relatos. Los valientes de David fueron sus guerreros más leales y capaces, quienes realizaron hazañas extraordinarias y formaron la columna vertebral de su poder militar. Los ahohítas contribuyeron con múltiples guerreros a las fuerzas de David, demostrando la lealtad de su clan al rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5867', 'spa', 'Elam (nombre propio; antiguo reino al este de Mesopotamia, frecuente objetivo profético)', 'Elam fue un antiguo reino situado al este de Mesopotamia, en lo que hoy es el suroeste de Irán. Según la Tabla de las Naciones, los elamitas descendían de Sem. Las Escrituras mencionan a Elam tanto en contextos históricos como proféticos; Jeremías 49 pronuncia juicio sobre esta nación, prometiendo dispersar a los elamitas a los cuatro vientos y quebrantar su poderío militar. Sin embargo, Dios también prometió su restauración futura. En Pentecostés, la presencia de elamitas en Hechos 2 evidencia el cumplimiento de esas promesas. El nombre llegó a representar una nación extranjera distante y poderosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5867a', 'spa', 'Elam -- antigua civilizacin y territorio al este de Mesopotamia (actual suroeste de Irn), pueblo descendiente de Sem y objeto de orculos profticos. No', 'Elam -- antigua civilizacin y territorio al este de Mesopotamia (actual suroeste de Irn), pueblo descendiente de Sem y objeto de orculos profticos. Nombre propio que identifica tanto al pueblo como al territorio de Elam, la antigua civilizacin centrada en lo que hoy es el suroeste de Irn, al este de las tierras bajas del Tigris. Gnesis 10:22 lista a Elam como ''hijo de Sem'', ubicndolo dentro del marco genealgico semtico a pesar de su lengua no semtica. En Gnesis 14, Quedorlaomer rey de Elam lidera una coalicin de reyes orientales contra Canan, una de las primeras referencias a la guerra internacional en las Escrituras. Los profetas pronuncian juicio sobre Elam (Jeremas 49:34-39) al tiempo que vislumbran su restauracin futura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5867b', 'spa', 'Elam (II) — nombre propio de persona y clan para varias familias postexílicas; distinto de la nación Elam', 'Este עֵילָם (Elam II) es un nombre de persona y clan distinto de la conocida nación al este de Babilonia. Designa a varios individuos y las familias descendientes de ellos que aparecen principalmente en las listas de retornados del exilio. Dos grupos separados de ''hijos de Elam'' regresaron de Babilonia: uno con 1.254 miembros (Esd 2:7; Neh 7:12) y otro llamado ''el otro Elam'' con igual número (Esd 2:31; Neh 7:34). Miembros del clan de Elam estuvieron entre quienes se habían casado con mujeres extranjeras (Esd 10:2, 26). Un benjaminita llamado Elam aparece en 1 Crónicas 8:24, un portero hijo de Coré en 1 Crónicas 26:3, y un líder que selló el pacto en Nehemías 10:14.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5868b', 'spa', 'Calor abrasador, ardor (dudoso; posiblemente ''con el ardor/vehemencia de su aliento''; texto incierto)', 'Este sustantivo es de significado incierto, pero probablemente denota calor abrasador, ardor o vehemencia. BDB sugiere una posible relación con voces árabes que expresan sed y calor interno. Aparece en la visión de Isaías donde el Señor golpea el río Éufrates y lo seca. La frase podría significar ''con el ardor de su aliento'' o ''con la vehemencia de su soplo'', aunque problemas textuales dificultan una lectura definitiva. Algunos proponen enmendar el texto a ''con la fuerza de''. Sea ''ardor'' o ''fuerza'', el sentido apunta al poder divino abrumador manifestado en su aliento o viento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5869', 'spa', 'Ojo; formas constructas con sufijos pronominales que expresan posesión o perspectiva', 'Estas tres apariciones representan construcciones gramaticales particulares de la palabra común «ojo», específicamente frases constructas con sufijos pronominales. Los contextos muestran el vocablo en expresiones idiomáticas: David esperando que Yahvé mire su aflicción «con Su ojo», Sedequías advertido de que hablará con Nabucodonosor «sus ojos frente a tus ojos» (cara a cara), y Yahvé ordenando «no tenga compasión vuestro ojo» al ejecutar juicio. Las formas constructas permiten la vívida imaginería hebrea de la vista, la percepción y el encuentro directo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5869a', 'spa', 'Ojo: en el modismo evaluativo ''a los ojos de'' (juicio/opinión); órgano físico de la vista; apariencia visible', 'El sustantivo hebreo עַיִן (''ojo'') es una de las palabras más versátiles de la Escritura. Precedido por las preposiciones לְ o בְּ funciona abrumadoramente como metáfora evaluativa: ''a los ojos de'' alguien significa ''según el juicio o la estimación de alguien''. Este uso idiomático abarca la gran mayoría de sus 872 apariciones: Noé ''halló gracia a los ojos del SEÑOR'' (Gn 6:8), y lo ''malo a los ojos del SEÑOR'' resuena como estribillo en Jueces y Reyes. El español ''a los ojos de'', el francés ''aux yeux de'' y el alemán ''in den Augen'' preservan esta metáfora con modismos corporales casi idénticos. El sentido literal de parte del cuerpo y el más raro de ''apariencia'' completan un perfil semántico compacto pero importante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5869b', 'spa', 'Manantial o fuente de agua; un nacimiento que brota de la tierra, frecuentemente en contextos geográficos o topónimos.', 'Manantial o fuente de agua; un nacimiento que brota de la tierra, frecuentemente en contextos geográficos o topónimos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5870', 'spa', 'Ojo (arameo) — el órgano físico de la vista, o figuradamente el ojo de Dios como vigilancia providencial', 'Cognado arameo del hebreo עַיִן, este sustantivo designa el ojo como órgano físico y como símbolo de percepción y vigilancia. En Esdras 5:5 se refiere al ojo de Dios que vela sobre los ancianos judíos, impidiendo toda interferencia con la reconstrucción del templo. En Daniel describe los inquietantes ojos humanos del cuerno pequeño (7:8, 20) y la restauración de la razón de Nabucodonosor cuando alza sus ojos al cielo (4:34). El término abarca así tanto la visión literal como la supervisión divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5871', 'spa', 'Ayin — topónimo que significa ''fuente''; un punto fronterizo de Canaán y una ciudad del Néguev en Judá/Simeón', 'Ayin (que significa ''fuente'' u ''ojo'') designa al menos dos localidades en la Biblia hebrea. Una marca un punto en la frontera nororiental de Canaán (Nm 34:11), donde la Septuaginta lo traduce como ἐπὶ πηγάς (''junto a las fuentes''). La otra identifica una ciudad en el Néguev asignada a Judá y posteriormente a Simeón, frecuentemente mencionada junto con Rimón (Jos 15:32; 19:7; 1 Cr 4:32), probablemente la actual Umm er-Ramamin al suroeste de Hebrón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5872', 'spa', 'En-gadi (''fuente del cabrito''), asentamiento oasis en la ribera occidental del mar Muerto, en el desierto de Judá', 'Topónimo compuesto que significa ''fuente del cabrito'' (ʿeyn + gedi), designa el célebre oasis en la ribera occidental del mar Muerto. Sus abundantes manantiales de agua dulce creaban un contraste llamativo con el desierto árido circundante, convirtiéndolo en refugio y lugar de belleza. David se escondió de Saúl en las fortalezas de En-gadi (1 Sam 23:29; 24:1), y el Cantar de los Cantares compara a la amada con los viñedos de En-gadi (Cnt 1:14). La visión escatológica de Ezequiel sitúa pescadores a lo largo de la costa desde En-gadi hasta En-eglaim (Ez 47:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5873', 'spa', 'En-ganim; ''fuente de jardines'', dos ciudades israelitas: una en Judá y otra en Isacar', 'En-ganim, que significa ''fuente de jardines'', identifica dos ciudades distintas en el antiguo Israel. Una se hallaba en las tierras bajas de la Sefela de Judá, posiblemente la moderna Umm Yina, cerca de Bet-semes. La otra, más significativa, estaba en Isacar: una ciudad levítica asignada a los levitas gersonitas. Este En-ganim del norte se identifica con Yenín, cerca del borde sureste del valle de Jezreel, a unos 24 kilómetros al norte-noreste de Samaria. El nombre evoca la imagen de un oasis irrigado, un manantial que alimenta jardines, recurso precioso en un entorno semiárido. La transmisión textual muestra corrupción en 1 Crónicas 6:58, donde aparece como Anem.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5874', 'spa', 'En-dor; «manantial de la morada», ciudad en Manasés célebre por la consulta de Saúl a la médium', 'En-dor, cuyo nombre significa «manantial de la morada» o «manantial de la generación», es célebre por ser el lugar donde Saúl consultó a una nigromante la víspera de su última batalla. Situada unos 22 km al norte-noreste del valle de Jezreel, la ciudad fue asignada a Manasés pero permaneció inicialmente bajo control cananeo (Josué 17:11). El Salmo 83:10 recuerda una victoria anterior allí, posiblemente la de Débora y Barac sobre Sísara. Su nombre ha quedado asociado para siempre con la necromancia y la consulta oculta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5875', 'spa', 'En-hacore (nombre de lugar, ''fuente del que clama/perdiz''; manantial que Dios proveyó para Sansón)', 'En-hacore es un topónimo que significa ''fuente del que clama'' o ''fuente de la perdiz'', y conmemora la provisión divina de agua para Sansón. Tras matar a mil filisteos con una quijada de asno, Sansón quedó desesperadamente sediento y clamó a Dios. Entonces Dios abrió una hendidura en la roca y brotó agua. Sansón llamó al manantial En-hacore porque había clamado a Dios en su necesidad extrema. El nombre captura tanto el grito de auxilio como la respuesta generosa de Dios. La fuente se hallaba en Lehi o sus cercanías, y siguió manando como testimonio permanente de la fidelidad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5876', 'spa', 'En-hada (nombre de lugar, ''fuente veloz''; ciudad en el territorio tribal de Isacar)', 'En-hada es un topónimo que posiblemente significa ''fuente veloz'' o ''fuente aguda'', combinando עֵין (fuente/manantial) con un adjetivo que sugiere rapidez o agudeza. Era una ciudad dentro de la asignación territorial de Isacar, mencionada en la lista de fronteras de Josué 19. Su ubicación exacta se desconoce, aunque se situaba en algún punto de la región del valle de Jezreel o las colinas circundantes. Los manantiales eran vitales para los asentamientos en el antiguo Israel, y las ciudades solían llevar el nombre de sus fuentes de agua. El adjetivo podría describir el flujo rápido del manantial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5877', 'spa', 'En-hasor (nombre de lugar, ''fuente de Hasor''; ciudad en el territorio tribal de Neftalí)', 'En-hasor aparece una sola vez en la lista de fronteras de la herencia de Neftalí. El nombre significa ''fuente de Hasor'', combinando el elemento común עֵין (fuente/manantial) con Hasor. La Septuaginta lo traduce como ''fuente de Asor'', preservando la conexión con las fuentes de agua que eran fundamentales para determinar los lugares de asentamiento. Era una de las ciudades fortificadas que marcaban las fronteras del territorio septentrional de Neftalí, en la distribución de la tierra bajo Josué.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5878', 'spa', 'Harod, manantial donde acampó el ejército de Gedeón antes de enfrentar a los madianitas', 'El manantial de Harod sirvió como punto de campamento estratégico para Gedeón y sus tropas. Fue el célebre lugar donde Dios redujo el ejército de Gedeón de miles a solo trescientos hombres mediante la prueba del agua. El nombre עֵין חֲרֹד podría estar vinculado con la idea de temblor o temor, reflejando quizá la ansiedad de los soldados sin experiencia en combate. Las traducciones modernas conservan con cuidado la forma «manantial de Harod» o «Ein Harod», manteniendo la precisión geográfica esencial para comprender la narrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5879', 'spa', 'Enam/Enaim; ciudad en la Sefelá de Judá, escenario del encuentro entre Judá y Tamar', 'Esta ciudad aparece bajo dos formas ligeramente distintas: Enam en la lista territorial de Josué y Enaim en el relato de Judá y Tamar. El nombre significa «dos manantiales», lo que sugiere un asentamiento junto a fuentes de agua dobles. Génesis 38 la sitúa en el camino a Timna, donde Tamar se apostó para interceptar a su suegro Judá, dando lugar a un encuentro escandaloso pero providencial del cual nació Fares, antepasado de David. Josué 15:34 la incluye entre las ciudades de la Sefelá de Judá. Las variantes textuales reflejan la fluidez ortográfica típica de los topónimos en la transmisión bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5880', 'spa', 'En-Mispat, otro nombre para Cades-Barnea que significa ''manantial del juicio''', 'En-Mispat es una designación alternativa para la importante localidad del desierto conocida como Cades-Barnea. El nombre significa ''manantial del juicio'' o ''fuente de la justicia'', reflejando posiblemente eventos legales o judiciales significativos que tuvieron lugar allí. La Septuaginta lo traduce literalmente como ''la fuente del juicio''. Esta identificación ayuda a conectar diversas narrativas del desierto, ya que Cades-Barnea fue central en la travesía de cuarenta años de Israel y figuró de manera prominente en episodios del liderazgo de Moisés y del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5881', 'spa', 'Enán — neftalita, padre de Ahira, mencionado en el censo y las ofrendas tribales del desierto', 'Enán es el padre de Ahira, el líder de la tribu de Neftalí durante el período del desierto. Su nombre aparece exclusivamente en Números en relación con el censo (Nm 1:15; 2:29), las ofrendas de dedicación del tabernáculo (Nm 7:78, 83) y el orden de marcha (Nm 10:27). El nombre probablemente derive de una raíz relacionada con ''fuentes'' u ''ojos'', acorde con el patrón onomástico hebreo más amplio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5882', 'spa', 'En-Eglaim, localidad en la orilla del Mar Muerto en la visión de restauración de Ezequiel', 'En-Eglaim aparece únicamente en la visión profética de Ezequiel sobre la tierra renovada. Situada en algún punto de la orilla del Mar Muerto, marca uno de los límites donde los pescadores tenderían sus redes en el paisaje transformado. El nombre significa ''manantial de los dos becerros'' o posiblemente ''manantial de las dos carretas''. En Ezequiel 47, el profeta contempla aguas vivificantes que fluyen del templo y sanan el Mar Muerto, haciéndolo abundar en peces: una inversión asombrosa de la desolación estéril de aquella región.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5883', 'spa', 'En-Rogel — ''fuente del batanero,'' manantial en el límite de Judá y Benjamín cerca de Jerusalén', 'En-Rogel (''fuente del batanero'' o ''fuente del pie'') era un importante manantial situado en la frontera entre los territorios tribales de Judá y Benjamín, cerca de la confluencia de los valles del Cedrón y del Hinom, al sur de Jerusalén. Funcionaba como hito geográfico clave en las descripciones de límites tribales (Jos 15:7; 18:16). Posteriormente adquirió relevancia en las intrigas políticas de la corte de David: Adonías celebró allí su banquete rival de coronación (1 R 1:9), y Jonatán y Ahimaas esperaron junto a la fuente como espías durante la revuelta de Absalón (2 S 17:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5884', 'spa', 'En-Rimón, asentamiento en la Judá postexílica, posiblemente la fusión de Aín y Rimón', 'En-Rimón fue repoblada por los exiliados que retornaron en tiempos de Nehemías. El nombre representa probablemente la unión de dos lugares antes distintos: Aín (''manantial'') y Rimón (''granada''), que se habían fusionado en un solo asentamiento. Zacarías 14:10 menciona Rimón como punto de referencia geográfico en el paisaje transformado de Jerusalén. La conservación de ambos elementos en el nombre compuesto refleja cómo los asentamientos antiguos solían desarrollarse en torno a fuentes de agua señaladas por rasgos distintivos del terreno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5887', 'spa', 'En-Tapúa, asentamiento en la frontera entre Efraín y Manasés', 'En-Tapúa marcaba un punto limítrofe en la compleja división territorial entre las tribus de José. El nombre significa ''manantial de la manzana'' o ''manantial de Tapúa'', vinculándolo con la ciudad cercana del mismo nombre. Las descripciones de fronteras en Josué prestan cuidadosa atención a las fuentes de agua y los pueblos establecidos que ayudaban a definir las herencias tribales. Esta localidad aparece en el detallado inventario que buscaba distribuir equitativamente la tierra entre las tribus, respetando los rasgos geográficos naturales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5888', 'spa', 'Desfallecer, estar exhausto; describe debilidad física extrema o desmayo', 'Este verbo describe la condición de estar físicamente vencido, desfallecido o exhausto. En Jeremías 4:31, retrata el alma de una mujer que desfallece, empleando la vívida metáfora de alguien en los dolores de parto que lucha por respirar. El término se relaciona con otras palabras hebreas para el agotamiento y aparece en contextos de angustia extrema. Aunque BDB señala incertidumbres textuales en algunas atestaciones, el significado central de debilidad física o colapso permanece constante donde aparece la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5889', 'spa', 'Cansado, desfallecido o agotado; describe la fatiga fsica por el esfuerzo, el viaje o la sed. Adjetivo de agotamiento corporal: la extenuacin profunda', 'Cansado, desfallecido o agotado; describe la fatiga fsica por el esfuerzo, el viaje o la sed. Adjetivo de agotamiento corporal: la extenuacin profunda del viajero, el soldado o el peregrino en tierra rida. Esa regresa del campo עָיֵף, tan exhausto que cambia su primogenitura por un guiso (Gn 25:29-30). Los hombres de Geden persiguen a los madianitas aunque estn עֲיֵפִים (Jue 8:4-5). La palabra adquiere especial intensidad cuando se extiende a la sed y al anhelo espiritual: ''tierra seca y sedienta donde no hay agua'' (Sal 63:2), o Dios que reconforta al ''alma desfallecida'' (Jer 31:25). La frontera entre el agotamiento fsico y un cansancio existencial ms profundo le da a esta palabra su hondura teolgica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5891', 'spa', 'Efa — nombre personal y de clan: una subtribu madianita y dos figuras en la genealogía de Judá', 'Efa aparece como nombre de tres figuras distintas en la Biblia hebrea. El más destacado es un ''hijo'' de Madián y nieto de Abraham a través de Cetura (Gn 25:4; 1 Cr 1:33), que representa un clan madianita cuyos camellos se vislumbran fluyendo hacia Sion en Isaías 60:6. Además, el nombre pertenece tanto a un descendiente varón de Judá (1 Cr 2:47) como a una concubina de Caleb (1 Cr 2:46) en las genealogías del Cronista. La Septuaginta traduce el nombre de diversas formas: Gafer, Gefar y Gaifa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5892b', 'spa', 'ir — ciudad o pueblo; cualquier asentamiento urbano habitado en el antiguo Cercano Oriente', 'El sustantivo femenino עִיר designa una ciudad o pueblo: cualquier asentamiento nucleado, normalmente amurallado, en contraste con el campo abierto o el campamento nómada. Aparece por primera vez en Gn 4:17, donde Caín edifica una ciudad, y sus 1.093 ocurrencias abarcan todos los períodos de la historia bíblica: desde la «gran ciudad» de Nínive (Gn 10:12) hasta las ciudades fortificadas de Judá y la ciudad escatológica de Dios. Las glosas interlingüísticas son notablemente estables — español ciudad, francés ville, alemán Stadt — todas apuntando a un único concepto nuclear de asentamiento urbano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5893', 'spa', 'Ir, nombre propio en la genealogía de Benjamín', 'Ir aparece en los registros genealógicos de los descendientes de Benjamín. El nombre es idéntico a la palabra hebrea común para «ciudad», lo cual genera cierta ambigüedad textual que los estudiosos han señalado. En 1 Crónicas 7:12 aparece en la frase «hijos de Ir», que teóricamente podría leerse como «hijos de la ciudad», aunque el contexto indica claramente un nombre de persona. La brevedad de las genealogías de Crónicas a menudo nos deja con información mínima sobre individuos que, no obstante, desempeñaron un papel en la preservación de las identidades tribales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5894', 'spa', 'Vigilante, ser despierto; seres angélicos descritos en las visiones de Daniel', 'Este enigmático término aparece únicamente en las visiones arameas de Daniel y designa a seres angélicos caracterizados por su vigilia y alerta perpetua. En Daniel 4, estos «vigilantes» descienden del cielo con decretos relativos al juicio de Nabucodonosor, actuando como mensajeros divinos que nunca duermen. La raíz se conecta con vocablos siríacos y arameos referidos al acto de estar despierto. La literatura judía antigua, especialmente 1 Enoc, desarrolló una angelología elaborada en torno a estos vigilantes, aunque su aparición bíblica se limita a Daniel. El término subraya el papel de estos ángeles como centinelas celestiales que observan y ejecutan los decretos de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5895', 'spa', 'Asno joven, pollino o potro; también un homógrafo que significa ciudad o pueblo (en Jueces 10:4)', 'Principalmente un sustantivo para un asno joven y vigoroso. Aparece en relatos patriarcales (Gn 32:15, diez pollinos entre el regalo de Jacob), en profecía mesiánica (Zac 9:9, ''montado sobre un asno, sobre un pollino'') y en imágenes poéticas (Gn 49:11, atando su pollino a la vid). La forma plural describe asnos usados para cabalgar por los hijos de los jueces (Jue 10:4; 12:14) y para llevar cargas (Is 30:24). Una ocurrencia en Jueces 10:4 es un conocido homógrafo: las ''treinta ciudades'' de Jaír, un juego de palabras con los treinta pollinos que montaban sus hijos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5896', 'spa', 'Ira, nombre propio de un sacerdote de David y dos de sus guerreros de élite (los ''valientes'').', 'Ira (עִירָא) es un nombre masculino propio, posiblemente relacionado con el sustantivo עִיר (''pollino de asno'') o con el elemento onomástico sabeo עיר. Tres hombres llevan este nombre, todos en el círculo íntimo de David: Ira el jairita, quien sirvió como sacerdote o ministro principal de David (2 Sam 20:26); Ira hijo de Iques, el tecoíta, uno de los treinta valientes de David (2 Sam 23:26 = 1 Cr 11:28; cf. 1 Cr 27:9); e Ira el itrita, otro de los treinta (2 Sam 23:38 = 1 Cr 11:40). La Septuaginta traduce el nombre como Eiras, y tanto el español como el francés y el inglés lo transliteran simplemente como ''Ira''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5898', 'spa', 'Ir-Hamelaj (Ciudad de la Sal), asentamiento no identificado en el desierto de Judá', 'Ir-Hamelaj significa literalmente «ciudad de la sal», nombre apropiado por su ubicación en la región desértica cercana al Mar Muerto. Mencionada junto a En-Gadi en la lista de ciudades del desierto de Judá en Josué, su sitio exacto sigue sin ser identificado por la arqueología moderna. La Septuaginta traduce el nombre literalmente como «ciudades de la sal», reflejando el entorno salino. Su asociación con En-Gadi sugiere que se encontraba en esa zona general, quizás como uno de los pequeños asentamientos que explotaban los recursos salinos de la región del Mar Muerto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5900', 'spa', 'Irú, descendiente de Caleb en la genealogía de Judá', 'Irú aparece en los registros genealógicos de la tribu de Judá como parte del linaje familiar de Caleb. La Septuaginta traduce el nombre como «Era» o «Ira», mostrando las ligeras variaciones comunes en la transmisión antigua de nombres propios. Primer Crónicas preserva muchos registros familiares que ayudan a rastrear el desarrollo de los clanes de Judá, e Irú representa a un individuo dentro de estas complejas redes genealógicas. Estas breves menciones nos recuerdan que la estructura tribal de Israel estaba compuesta por familias reales cuyas historias se extendían a lo largo de generaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5901', 'spa', 'Iri, benjaminita listado entre los descendientes de Bela', 'Iri aparece en los registros genealógicos de Benjamín, específicamente entre los hijos de Bela, el primogénito de Benjamín. La Septuaginta traduce este nombre como «Ourei» u «Ouri», mostrando las variaciones típicas en la transmisión de nombres propios. Las genealogías de Benjamín en Crónicas son particularmente detalladas, quizá debido al pequeño tamaño de la tribu y su posición estratégica entre Judá y las tribus del norte. Cada nombre preservado en estas listas representaba a un jefe de familia cuyos descendientes ayudaron a mantener la identidad tribal a través de circunstancias históricas cambiantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5903', 'spa', 'Desnudo, sin ropa (adjetivo); o desnudez como condición abstracta de exposición y vulnerabilidad.', 'Adjetivo y sustantivo derivado de la raíz ayin-vav-resh que significa ''desnudo'' o ''desnudez''. Sus apariciones más memorables están en Génesis 3:7-11, donde Adán y Eva descubren que están desnudos tras comer del fruto prohibido, escena primordial de exposición y vergüenza. Ezequiel lo reutiliza para la Jerusalén personificada, hallada desnuda como recién nacida (16:7) y despojada en juicio (16:22, 39; 23:29). Deuteronomio 28:48 lo usa abstractamente: servir a los enemigos ''en desnudez'', condición de total privación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5904', 'spa', 'Ir-Najas (Ciudad de Najas), posiblemente nombrada por una persona o que significa ''ciudad de bronce/serpiente''', 'Ir-Najas aparece en los registros genealógicos de Judá con un nombre intrigante que podría significar ''ciudad de la serpiente'', ''ciudad del bronce'', o derivar de una persona llamada Najas. Este era el nombre del rey amonita que amenazó a Jabes de Galaad en tiempos de Saúl, y posiblemente el padre de Sarvia y Abigaíl. La Septuaginta lo traduce como ''ciudad de Naas'', tratando a Najas como nombre propio. Esto ilustra cómo los topónimos hebreos frecuentemente preservaban la memoria histórica de fundadores o eventos significativos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5905', 'spa', 'Ir-Semes (Ciudad del Sol), pueblo en el territorio de Dan, idéntico a Bet-Semes', 'Ir-Semes significa ''ciudad del sol'', revelando la asociación del lugar con referencias solares frecuentes en la toponimia cananea. El texto lo identifica con Bet-Semes (''casa del sol''), una de las ciudades más prominentes de la región. Tales nombres probablemente reflejan conexiones religiosas cananeas previas a Israel relacionadas con el culto solar, aunque los sitios fueron plenamente integrados al sistema tribal israelita. La traducción de la Septuaginta como ''ciudad de Sames'' preserva tanto el elemento urbano como la conexión solar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5907', 'spa', 'Acbor, nombre propio que significa ''ratón,'' llevado por un patriarca edomita y un oficial de la corte de Josías', 'El nombre Acbor (que significa ''ratón'') pertenece a al menos dos figuras bíblicas distintas. El primero es el padre del rey edomita Baal-Hanán (Gn 36:38-39). El segundo es el padre de Elnatán, un cortesano durante el reinado del rey Josías que participó en la recuperación del rollo de la Ley recién hallado (2 R 22:12, 14). El significado zoológico del nombre está bien documentado en la onomástica semítica noroccidental, con paralelos en nombres de animales en la tradición latina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5909', 'spa', 'Ratón o rata; roedor clasificado como ritualmente impuro, y modelado en oro como ofrenda expiatoria por los filisteos.', 'El sustantivo עַכְבָּר (akhbar) designa un ratón o rata, el roedor común, con cognados en arameo (עַכְבְּרָא) y árabe (عكابر). Aparece en dos contextos vívidos: la lista de criaturas impuras que se arrastran en el Código de Santidad (Lev 11:29) y la narrativa de la plaga filistea, donde se fabricaron ratones de oro como ofrendas de culpa junto con tumores de oro (1 Sam 6:4-18). Isaías 66:17 menciona el consumo de ratones como parte de rituales paganos abominables. La evidencia multilingüe confirma uniformemente un único referente zoológico en todos los pasajes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5910', 'spa', 'Aco, ciudad portuaria fenicia en el territorio de Aser (luego Ptolemaida, hoy Acre)', 'Aco fue un importante puerto mediterráneo que Aser no logró conquistar, permitiendo que permaneciera como bastión cananeo-fenicio. Situada al norte del Monte Carmelo, se convirtió en una de las ciudades costeras más estratégicas de la región, conocida después por su nombre griego Ptolemaida y su nombre cruzado Acre. La ciudad aparece en registros egipcios como ''A-ka y en textos asirios como ''Akku, lo que demuestra su antigua importancia. La incapacidad de Aser para tomar este puerto estratégico ilustra la naturaleza incompleta de la conquista y la coexistencia de Israel con la presencia cananea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5911', 'spa', 'Acor — ''turbación,'' un valle al oeste de Jericó nombrado por la perturbación causada por el pecado de Acán', 'Acor (''turbación'' o ''perturbación'') designa un valle al oeste o suroeste de Jericó donde Acán fue ejecutado por tomar objetos consagrados al anatema tras la caída de Jericó (Jos 7:24, 26). El nombre es etiológico, pues explica el lugar mediante el verbo עָכַר (''turbar, perturbar''). Además de servir como hito fronterizo de Judá (Jos 15:7), el valle de Acor adquiere un profundo sentido profético: Oseas 2:15 promete que se convertirá en ''puerta de esperanza,'' e Isaías 65:10 lo describe como lugar de reposo para los rebaños en la creación renovada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5912', 'spa', 'Acán, el hombre de Judá que tomó botín consagrado de Jericó, trayendo desastre sobre Israel en Hai (Jos 7).', 'Acán (עָכָן) es el hombre de la tribu de Judá que violó el anatema (חֵרֶם) sobre el botín de Jericó al tomar en secreto un manto babilónico, plata y una barra de oro (Jos 7:1, 18-24). Su robo provocó la devastadora derrota de Israel en Hai, y tras ser identificado mediante sorteo sagrado, él y toda su familia fueron apedreados y quemados en el Valle de Acor. La variante ortográfica עָכָר en 1 Crónicas 2:7 vincula etimológicamente su nombre con עָכוֹר (''turbación''), tal como Josué declaró: ''¿Por qué nos has turbado (עֲכַרְתָּנוּ)?'' La Septuaginta lo traduce sistemáticamente como Acar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5913', 'spa', 'tintinear, hacer sonar (ajorcas o tobilleras); usado para describir la ostentosa ornamentación femenina', 'Este verbo describe el sonido deliberado de tintineo o cascabeleo producido por adornos de tobillo usados por mujeres adineradas. Isaías lo emplea en su severa crítica contra las mujeres de la élite de Jerusalén que desfilaban por las calles con actitudes afectadas. El sonido de las joyas entrechocándose intencionalmente a cada paso simbolizaba vanidad, lujo y complacencia moral. La forma denominativa Piel sugiere acción deliberada: las mujeres provocaban estos sonidos a propósito, atrayendo la atención mediante una exhibición tanto visual como auditiva de su riqueza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5915', 'spa', 'Acsa — hija de Caleb que pidió y recibió manantiales de agua como regalo de bodas', 'Acsa fue la hija de Caleb, dada en matrimonio a Otoniel hijo de Quenaz como recompensa por conquistar Quiriat-Séfer (Jos 15:16-17; Jue 1:12-13). Es recordada por pedir audazmente a su padre no solo la tierra del Néguev que le había dado, sino también los manantiales superiores e inferiores, petición que él concedió. Su relato aparece en forma casi idéntica en Josué y Jueces, y el Cronista preserva su nombre en la genealogía de Caleb (1 Cr 2:49). La Septuaginta alterna entre Asja, Acsa y Oxa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5916', 'spa', 'Turbar, agitar, acarrear calamidad; en Nifal, ser turbado o perturbado.', 'Un verbo de disrupción y perturbación, célebremente asociado con Acán, cuyo pecado ''turbó'' a todo Israel (Jos 7:25). El sentido activo del Qal describe acarrear calamidad o causar conmoción: Elías devuelve la acusación a Acab en 1 Reyes 18:17–18, preguntando quién verdaderamente ''turba a Israel''. Proverbios emplea la palabra para la perturbación que el codicioso se acarrea a sí mismo (11:17, 29; 15:27). El Nifal pasivo aparece en el Salmo 39:2, donde el dolor del salmista ''se agitó'', y en Proverbios 15:6, describiendo un hogar en turbación. El cognado árabe ''akira (estar turbio) conserva la imagen física de aguas enturbiadas, vívida metáfora de la disrupción social y personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5917', 'spa', 'Acar (Acán), el judahita que tomó del anatema en Jericó, trayendo desgracia sobre Israel', 'Acar es la grafía alternativa de Acán, cuyo robo de objetos consagrados al anatema tras la caída de Jericó provocó la devastadora derrota en Hai. Primer Crónicas usa esta forma, que significa ''perturbador'', jugando con la palabra hebrea עָכַר (''turbar, perturbar''). Josué 7:26 establece explícitamente esta conexión: ''Por eso aquel lugar se llama Valle de Acor hasta hoy''. El relato ilustra la responsabilidad colectiva en la comunidad del pacto: el pecado de un solo individuo afectó a todo Israel. La confesión de Acán y su posterior ejecución en el Valle de Acor se convirtieron en un recordatorio permanente de la gravedad de violar los mandamientos de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5918', 'spa', 'Ocrán — hombre aserita, padre de Pagiel, mencionado en el censo del desierto y las ofrendas tribales', 'Ocrán es el padre de Pagiel, quien sirvió como líder de la tribu de Aser durante el período del desierto. Al igual que otros padres tribales en Números, Ocrán aparece exclusivamente en las listas formulares del censo (Nm 1:13; 2:27), las ofrendas de dedicación del tabernáculo (Nm 7:72, 77) y el orden de marcha (Nm 10:26). La Septuaginta traduce el nombre como Ecrán, lo que sugiere una pronunciación con apertura gutural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5919', 'spa', 'Serpiente venenosa, probablemente una víbora o áspid; alternativamente, una araña (texto incierto)', 'Esta palabra poco frecuente aparece únicamente en el Salmo 140:3, describiendo el veneno de criaturas peligrosas como metáfora del habla de los enemigos. Las versiones antiguas generalmente la interpretaron como un tipo de serpiente venenosa, específicamente una víbora o áspid. Sin embargo, algunos eruditos sugieren que podría ser una corrupción textual de עַכָּבִישׁ (araña), dado el contexto similar en Job. El Targum apoya la interpretación de araña, mientras que las versiones griega y latina prefirieron la identificación como serpiente. En cualquier caso, el salmo emplea la imagen del veneno mortal para caracterizar el habla calumniosa y destructiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5920', 'spa', 'altura, hacia arriba; usado poéticamente para elevación física y metafóricamente para ascenso moral o espiritual hacia Dios', 'Un término poético que expresa tanto la altura literal como la elevación espiritual. En 2 Samuel 23:1, David es descrito como ''levantado en lo alto'', combinando exaltación política con favor divino. Los profetas lo emplean metafóricamente: Oseas lamenta que Israel ''vuelve pero no hacia arriba'', es decir, no hacia Dios, a pesar de los llamados proféticos a elevarse espiritualmente. La imagen espacial de ''arriba'' y ''hacia lo alto'' se extiende naturalmente a conceptos teológicos de buscar al Altísimo, preservando tanto la dimensión espacial como la teológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5921', 'spa', 'Preposición aramea עַל: sobre, encima de (espacial); acerca de, tocante a (temático); contra (adversativo).', 'La preposición aramea עַל en Daniel y Jeremías posee el mismo triple alcance que su cognado hebreo. Su sentido primario es espacial: ''sobre'' o ''encima de'' alguien, como cuando la soberanía se establece ''sobre'' el reino de los hombres (Dn 4:17, 32). En Daniel 5:14, 16 adquiere sentido temático: ''acerca de ti'' o ''tocante a ti'', cuando los informes sobre la sabiduría de Daniel llegan al rey. El uso más infrecuente es el adversativo: en Jeremías 49:30, Nabucodonosor traza un plan ''contra ustedes'', donde la intención hostil resulta inequívoca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5921a', 'spa', 'sobre, en, encima de; contra; junto a, al lado de; a causa de, por lo tanto; acerca de, concerniente a; por, en favor de; hacia, a; según, además de', 'La preposición hebrea más frecuente con 5,769 ocurrencias, expresando una gama notable de conexiones espaciales, relacionales y lógicas. El núcleo es el contacto físico con una superficie: ''sobre la tierra'', ''en el altar'', ''sobre las aguas''. De esta base espacial se extiende la fuerza adversativa (''levantarse contra''), la proximidad (''se paró junto al pozo''), la causalidad (''a causa de esto'', ''por lo tanto''), el tema (''acerca de este asunto''), el beneficio (''expiar por''), la dirección (''vino hacia ellos''), y la norma (''según sus familias''). Las traducciones multilingües revelan qué sentido opera en cada contexto, ya que diferentes idiomas seleccionan preposiciones distintas para cada dominio semántico mientras el hebreo usa esta sola forma altamente polisémica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5921b', 'spa', 'Preposición compuesta ''porque, por esta razón''; partícula causal enfática que refuerza el fundamento de una afirmación o acción.', 'La frase כִּי עַל כֵּן combina tres partículas en una expresión enfática que significa ''porque'' o ''por cuanto''. Aparece en momentos narrativos memorables, reforzando la razón detrás de una acción con fuerza pleonástica — literalmente ''pues sobre así''. Abraham la usa al recibir a sus visitantes en Mamré (Gn 18:5), y Lot la repite al instar a los ángeles a quedarse (Gn 19:8). El español capta el peso causal con ''por eso'', y el francés con ''c''est pourquoi''. En Gn 33:10, la súplica de Jacob a Esaú se inclina hacia un ''por tanto'' consecutivo, extrayendo una conclusión más que enunciando una causa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5922', 'spa', 'Preposición aramea: sobre, encima de; a, hacia; acerca de; contra; a causa de; más que', 'Preposición aramea que aparece exclusivamente en las secciones bilingües de Esdras y Daniel, funcionando como equivalente del hebreo ''al. Su núcleo espacial significa ''sobre'' o ''encima de'', pero el contexto la extiende a un amplio abanico: dirección (''a, hacia''), tema (''acerca de''), oposición (''contra''), causa (''a causa de'') e incluso comparación (''más que''). La furia de Nabucodonosor ardió ''contra'' los tres jóvenes (Dn 3:19), mientras la misma forma en el mismo versículo expresa grado: su rostro se demudó ''más de'' lo acostumbrado. Rastrear sus formas sufijadas a lo largo de los capítulos arameos revela cómo una sola preposición ancla toda una red de significados relacionales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5923', 'spa', 'Yugo -- barra de madera para animales de tiro; figuradamente, la carga de servidumbre, opresion o subyugacion', 'Yugo -- barra de madera para animales de tiro; figuradamente, la carga de servidumbre, opresion o subyugacion');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5924', 'spa', 'Encima, sobre (arameo); indica posición espacial de autoridad o superioridad', 'Este adverbio arameo indica posición espacial: estar encima o sobre algo o alguien. En Daniel 6:3, describe la alta posición de autoridad que ciertos funcionarios ocupaban sobre otros dentro del sistema administrativo persa. La palabra se forma con la terminación direccional característica del arameo. Es paralela al hebreo עַל pero aparece específicamente en las porciones arameas de Daniel y Esdras. El término se extiende naturalmente de la altura física a la superioridad jerárquica, reflejando cómo las culturas del antiguo Cercano Oriente conceptualizaban la autoridad en términos espaciales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5925', 'spa', 'Ula, un descendiente de Aser mencionado en las genealogías tribales', 'Ula aparece entre los descendientes de Aser en los registros genealógicos de Crónicas. El nombre es breve y su significado incierto, aunque podría estar relacionado con elevación o altura. La Septuaginta lo traduce como «Ola», mostrando la variación típica en la transliteración griega de nombres hebreos. Estos registros genealógicos cumplían funciones importantes en el Israel postexílico, estableciendo identidades tribales y reclamos territoriales que habían sido interrumpidos por el exilio y la dominación extranjera. Cada nombre preservado representaba un linaje familiar que mantuvo la identidad de Aser a través de las generaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5926', 'spa', 'Tartamudo, que habla con dificultad o de manera confusa (impedimento del habla o acento extranjero)', 'Este adjetivo describe el habla confusa, vacilante o tartamuda: la lengua que tropieza con las palabras. En Isaías 32:4 aparece en una profecía sobre el reino transformado donde incluso quienes antes tartamudeaban hablarán con claridad y fluidez. La Septuaginta emplea un término griego específico para el tartamudeo o ceceo. La palabra podría referirse a impedimentos reales del habla o al habla confusa de extranjeros que hablaban hebreo con dificultad. Isaías vislumbra una renovación donde toda forma de limitación será superada en la era mesiánica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5927', 'spa', 'subir, ascender; ofrecer sacrificio; hacer subir, sacar; levantarse; ser alzado; encender lámparas; rumiar', 'Verbo de extraordinaria amplitud semántica, עָלָה significa fundamentalmente subir o ascender, ya sea al escalar una montaña, viajar a Jerusalén o acercarse a la presencia de Dios. De esta raíz física brotan algunas de las metáforas teológicas más importantes de la Biblia: las ofrendas «suben» como humo al cielo (Gn 8:20; 22:13), Dios «hace subir» a Israel de Egipto (Éx 3:8) y la luz de la mañana «se levanta» sobre la creación (Gn 19:15; 32:26). Incluso las leyes técnicas sobre los animales que «hacen subir» el bolo alimenticio (Lv 11:4) y los sacerdotes que hacen «subir» la luz del candelabro (Éx 25:37) comparten esta misma raíz direccional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5928', 'spa', 'Holocaustos (plural arameo); animales completamente consumidos por el fuego como sacrificios a Dios', 'Este término arameo designa los holocaustos, los sacrificios completamente consumidos por el fuego sobre el altar. Corresponde al hebreo עֹלָה, compartiendo la misma raíz etimológica relacionada con «subir» (en referencia al humo que asciende). Esdras 6:9 emplea esta palabra en el decreto persa que autorizaba el sistema sacrificial del templo de Jerusalén, mostrando cómo incluso las autoridades extranjeras reconocían y apoyaban las prácticas de culto del pueblo judío que regresaba. La forma plural indica la naturaleza regular y continua de estas ofrendas en el culto del templo restaurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5929', 'spa', 'Hoja o follaje, usado literalmente de hojas de rboles y figuradamente para el marchitarse o florecer; en plural constructo, ramas frondosas. Este sust', 'Hoja o follaje, usado literalmente de hojas de rboles y figuradamente para el marchitarse o florecer; en plural constructo, ramas frondosas. Este sustantivo comn designa la hoja de un rbol, una de las imgenes naturales ms evocadoras de la Biblia. Las primeras vestiduras humanas se cosen con hojas de higuera (Gn 3:7), y la paloma regresa a No con una hoja de olivo (Gn 8:11). El Salmo 1:3 retrata al justo como un rbol ''cuya hoja no se marchita'', mientras Isaas y Jeremas usan la hoja que se marchita como metfora del declive espiritual (Is 1:30; 64:6; Jer 8:13). En Nehemas 8:15, la forma de plural constructo se refiere a ramas frondosas recogidas para construir las cabanas de la fiesta de los Tabernculos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5930a', 'spa', 'Holocausto — sacrificio animal consumido enteramente por el fuego sobre el altar como ofrenda ascendente a Dios', 'La olah es el sacrificio ascendente por excelencia del culto hebreo: un animal enteramente consumido sobre el altar, cuyo humo sube a Dios como expresión de dedicación total. Desde el primer altar de Noé tras el diluvio (Gn 8:20), pasando por las elaboradas regulaciones levíticas (Lv 1:3-17) hasta las dedicaciones del templo de Salomón (1 R 3:4), esta ofrenda aparece casi 290 veces. El nombre mismo, de la raíz ''subir'', encierra la teología del ascenso: la víctima entera se eleva hacia el cielo. El español ''holocausto'' conserva el griego holokauston (''enteramente quemado''), mientras que el alemán Brandopfer (''ofrenda de fuego'') enfatiza la llama que consume.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5931', 'spa', 'Asunto, causa, ocasión; motivo de acusación o cargo legal', 'Este sustantivo arameo designa un asunto, causa u ocasión, especialmente en contextos jurídicos. Sus tres apariciones en Daniel 6 se refieren a la búsqueda de «motivos de acusación» contra Daniel por parte de los funcionarios del reino. Incapaces de hallar corrupción o negligencia en su administración, conspiraron para crear un pretexto religioso que lo condenara. La palabra representa el cargo formal que intentaban presentar contra él. Emparentada con términos siríacos para «causa» u «ocasión», subraya la dimensión legal de su complot. El hecho de que no encontraran ningún motivo atestigua la integridad de Daniel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5932', 'spa', 'iniquidad, injusticia, maldad; conducta violenta contraria a la rectitud que Dios exige', 'Este sustantivo designa la injusticia, la maldad y la perversión activa, es decir, lo opuesto a la justicia y equidad que Dios demanda. Aparece frecuentemente en textos poéticos que describen tanto la maldad humana como el carácter de quienes se oponen a Dios. Oseas 10:9 lo emplea en la frase «hijos de iniquidad», refiriéndose a los que obran el mal. El término subraya la naturaleza agresiva del pecado: no se trata de una simple falta moral, sino de una injusticia violenta que causa daño a otros. Los Salmos y los profetas contrastan esta iniquidad con la justicia de Dios, estableciéndola como incompatible con su presencia y destinada al juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5933', 'spa', 'Alvá/Alías; jefe edomita mencionado en las genealogías de Génesis y Crónicas', 'Este nombre aparece en las genealogías de los jefes edomitas descendientes de Esaú, con grafías variantes en la tradición masorética. Génesis 36:40 presenta la forma Alvá, mientras que 1 Crónicas 1:51 muestra tanto el Ketiv (Alías) como el Qeré (Alvá), lo que ilustra la variación textual en la transmisión de nombres propios. Este individuo figura entre los «jefes de Edom» según sus clanes y regiones. Las diversas formas griegas de la Septuaginta (Gola, Aloua) muestran que los traductores antiguos ya lidiaban con las mismas incertidumbres textuales. La etimología del nombre es incierta, aunque podría relacionarse con raíces que sugieren altura o exaltación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5934', 'spa', 'juventud, vigor juvenil — la plenitud de la vida marcada por fuerza y vitalidad, siempre en forma plural abstracta', 'Este sustantivo abstracto en plural designa el periodo y la energía de la juventud, y aparece siempre con sufijos posesivos (''su juventud'', ''tu juventud''). En Job 20:11, el vigor juvenil llena los huesos del impío solo para yacer con él en el polvo, una imagen conmovedora de vitalidad desperdiciada. Job 33:25 lo emplea para describir la renovación de la carne a un estado juvenil, mientras que el Salmo 89:45 lamenta la juventud acortada de un rey. Isaías 54:4 promete que la vergüenza de la juventud será olvidada en la restauración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5936', 'spa', 'sanguijuela, criatura chupasangre usada proverbialmente para la codicia insaciable', 'La sanguijuela aparece en Proverbios 30:15 como símbolo de un deseo insaciable. Este animal es conocido por su persistente succión de sangre, sin quedar jamás satisfecho. El proverbio la utiliza para introducir un dicho numérico sobre cosas que nunca dicen «basta»: el Seol, la matriz estéril, la tierra sedienta y el fuego. Algunos intérpretes antiguos sugirieron que podría referirse a un demonio vampírico o incluso al nombre de un sabio, pero la lectura literal como sanguijuela encaja perfectamente con el uso que hace la literatura sapiencial de la observación natural para la instrucción moral. La imagen captura vívidamente el deseo voraz y parasitario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5937', 'spa', 'Exultar, regocijarse jubilosamente -- triunfar con gozo exuberante, usado para la alabanza a Dios, el regocijo csmico e incluso la jactancia de los ma', 'Exultar, regocijarse jubilosamente -- triunfar con gozo exuberante, usado para la alabanza a Dios, el regocijo csmico e incluso la jactancia de los malvados. Verbo que expresa un gozo exuberante, incluso exttico, ms intenso que la alegra ordinaria, que connota exultacin triunfante. Habacuc 3:18 captura su ncleo teolgico: ''me regocijar en el Dios de mi salvacin'', emparejndolo con el sinnimo gîl. Sofonas 3:14 convoca a la hija de Sin a ''!exultar!'' junto con el canto y el regocijo. Sin embargo, la palabra no se reserva para los justos: Jeremas 50:11 y el Salmo 94:3 la aplican a enemigos y malvados que se jactan de su xito pasajero. Hasta la creacin se une: el Salmo 96:12 hace que los campos exulten ante el Seor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5938', 'spa', 'exultante, jubiloso, triunfante; quien se regocija ruidosamente', 'Este adjetivo describe a alguien en estado de exultación: un regocijo jubiloso y triunfante. En Isaías 5:14, caracteriza a quienes celebran en Jerusalén ajenos al juicio venidero. El profeta retrata al Seol abriendo su boca para tragar a los nobles, las multitudes y «al que se regocija» en Jerusalén, aquellos que festejan y se entregan al desenfreno sin tener en cuenta la obra de Dios. El término captura una celebración bulliciosa y autocomplaciente que, en el contexto de Isaías, se convierte en trágica ironía, pues quienes se deleitan están a punto de descender a la muerte. Subraya el peligro espiritual de la autosatisfacción despreocupada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5939', 'spa', 'oscuridad densa, penumbra profunda; tinieblas del anochecer o de la noche usadas para encubrimiento', 'Esta palabra describe la oscuridad profunda del crepúsculo o de la noche, particularmente cuando se emplea para ocultar algo. En Génesis 15:17, marca la tiniebla misteriosa que acompaña el pacto de Dios con Abraham. Ezequiel la utiliza tres veces para la oscuridad bajo la cual el profeta realiza su acción simbólica del exilio, sacando sus pertenencias en la penumbra como señal de la cautividad venidera de Jerusalén. El término implica más que la simple ausencia de luz: sugiere una lobreguez espesa que oculta acciones o acontecimientos, sirviendo funciones tanto literales como simbólicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5940', 'spa', 'pilón, mano de mortero; instrumento para moler o machacar grano en un mortero', 'El pilón o mano de mortero era el instrumento utilizado junto con el mortero para triturar grano, especias u otros materiales. Proverbios 27:22 lo emplea en una metáfora contundente: aunque machaques al necio con un pilón en un mortero entre el grano, no le quitarás su necedad. La imagen evoca un golpeteo vigoroso y repetido, la clase de fuerza necesaria para desmenuzar el grano. Sin embargo, el proverbio enseña que la necedad es aún más obstinada que el grano; no puede arrancarse de alguien solo mediante el castigo. Esto refleja la comprensión de la literatura sapiencial de que el cambio verdadero requiere más que fuerza externa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5941', 'spa', 'Eli -- el anciano sacerdote en Silo que crio a Samuel y cuya casa cayo bajo juicio divino', 'Eli -- el anciano sacerdote en Silo que crio a Samuel y cuya casa cayo bajo juicio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5943', 'spa', 'Altísimo: epíteto divino arameo que designa a Dios como soberano supremo, usado exclusivamente en Daniel. El adjetivo arameo en estado enfático signif', 'Altísimo: epíteto divino arameo que designa a Dios como soberano supremo, usado exclusivamente en Daniel. El adjetivo arameo en estado enfático significa ''el más alto'' o ''el más excelso'', y funciona como título de Dios a lo largo de las secciones arameas de Daniel. Aparece tanto con el sustantivo para Dios, como ''el Dios Altísimo'' (Dan 3:26; 5:18, 21), como de manera independiente, ''el Altísimo'' (Dan 4:14, 21, 22, 29, 31; 7:25). El término subraya la soberanía absoluta de Dios sobre los reinos terrenales, tema central en la humillación y restauración de Nabucodonosor (Dan 4). Su variación ketiv-qere (escrito como illai, leído como illaa) refleja la convención ortográfica aramea típica. El epíteto es paralelo al hebreo Elyon que se encuentra en Génesis 14 y los Salmos, extendiendo la misma teología de supremacía divina a las narrativas cortesanas arameas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5944', 'spa', 'Aposento alto o cámara en la azotea para intimidad y devoción; los aposentos celestiales de Dios; una escalera o subida. El sustantivo עֲלִיָּה design', 'Aposento alto o cámara en la azotea para intimidad y devoción; los aposentos celestiales de Dios; una escalera o subida. El sustantivo עֲלִיָּה designa la habitación construida sobre la azotea plana de una casa del Cercano Oriente —fresca, apartada y elevada sobre el ajetreo cotidiano. En la narrativa de Jueces, Eglón es asesinado en su עֲלִיָּה privada (Jue 3:20-25), y Elías lleva al hijo muerto de una viuda al aposento alto donde ora y el niño revive (1 Re 17:19). Daniel ora tres veces al día en su עֲלִיָּה con las ventanas abiertas hacia Jerusalén (Dan 6:10). El cognado siríaco ʿellithā y el arameo ʿălithā confirman el sentido arquitectónico a través de las lenguas semíticas. Notablemente, los Salmos elevan este humilde espacio doméstico a proporciones cósmicas: Dios ''puso las vigas de sus altos aposentos sobre las aguas'' (Sal 104:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5945a', 'spa', 'Superior o más alto en posición; elevado o exaltado en rango; Altísimo como título divino.', 'Superior o más alto en posición; elevado o exaltado en rango; Altísimo como título divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5945b', 'spa', 'Altísimo — título divino que enfatiza la soberanía suprema de Dios por encima de todos los poderes y naciones', 'Altísimo — título divino que enfatiza la soberanía suprema de Dios por encima de todos los poderes y naciones');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5946', 'spa', 'Altísimo; título divino arameo que enfatiza la soberanía suprema de Dios, usado exclusivamente en las visiones de Daniel', 'Un título arameo para Dios que significa ''Altísimo'', presente únicamente en Daniel 7, donde describe a los santos que reciben el reino. La forma de doble plural (''santos del Altísimo'') intensifica tanto la santidad del pueblo como la supremacía de Dios. Este título subraya la soberanía divina sobre todos los reinos terrenales, tema central en las visiones apocalípticas de Daniel, donde los imperios humanos se levantan y caen mientras el reinado de Dios permanece. El superlativo ''Altísimo'' preserva la naturaleza excelsa del nombre divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5947', 'spa', 'Exultante, jubiloso; describe ciudades o personas marcadas por un regocijo ruidoso y triunfal', 'Este adjetivo capta un estado de exultación ruidosa y triunfal, aplicado frecuentemente a ciudades personificadas que se deleitan en su prosperidad. Isaías lo emplea repetidamente para caracterizar lugares como Jerusalén y Tiro antes de su caída (Is 22:2; 23:7), y Sofonías lo aplica a Nínive (Sof 2:15). La palabra conlleva un matiz de ironía en el discurso profético: la jubilación que describe está típicamente a punto de ser silenciada por el juicio divino. Tanto ''exultante'' en español como ''triomphant'' en francés captan el tono de celebración orgullosa y estridente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5948', 'spa', 'horno, crisol o taller (incierto); lugar o instrumento para refinar metal', 'Esta palabra rara y difícil aparece únicamente en el Salmo 12:6, donde la plata refinada en un horno sirve como metáfora de la pureza de las palabras de Dios. El texto dice literalmente «plata refinada en un crisol para la tierra», aunque su significado preciso sigue siendo debatido. Las versiones antiguas y la tradición rabínica lo entendieron como horno o crisol, enfocándose en el proceso de refinamiento. Algunos eruditos modernos sugieren «taller» o incluso lo eliminan como glosa. Sea cual fuere el sentido técnico exacto, el mensaje del salmo es claro: las palabras de Dios están completamente probadas y son puras, a diferencia del habla humana caracterizada por mentiras y adulación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5949', 'spa', 'Hecho, acto u obra (ya sea de Dios o de los humanos); también una acusación inventada o cargo sin fundamento en contextos legales', 'Hecho, acto u obra (ya sea de Dios o de los humanos); también una acusación inventada o cargo sin fundamento en contextos legales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5950', 'spa', 'obra, acción; referido específicamente a las grandes obras de Dios', 'Este sustantivo femenino designa una obra o acción poderosa. Aparece únicamente en Jeremías 32:19, donde describe las acciones de Dios. El profeta declara que Dios es «grande en consejo y poderoso en obra», subrayando tanto la sabiduría divina en sus planes como su poder en la ejecución. El término puede ser una variante de la forma más común עֲלִילָה. En el contexto, Jeremías debe comprar un campo mientras Jerusalén enfrenta el asedio, confiando en que los propósitos de Dios prevalecerán a pesar de las apariencias. Sus obras cumplen fielmente su sabio consejo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5951', 'spa', 'exultación, regocijo; celebración jubilosa (con connotaciones oscuras en contexto)', 'Este sustantivo describe la exultación o el regocijo jubiloso. En Habacuc 3:14 aparece en un contexto perturbador: la exultación de los opresores era «como para devorar al pobre». El profeta retrata a enemigos malvados que se regocijan en la violencia y la explotación, celebrando mientras destruyen a los vulnerables. Su gozo está pervertido, hallando deleite en la crueldad en vez de la justicia. La teofanía de Habacuc presenta a Dios viniendo en juicio contra tales opresores. El término capta cómo la celebración puede invertirse moralmente cuando se regocija en el mal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5952', 'spa', 'aposento alto, cámara superior (arameo); habitación elevada para oración y devoción privada', 'Este término arameo designa un aposento alto o cámara superior, equivalente al hebreo עֲלִיָּה. En Daniel 6:10 se describe cómo Daniel subía a su aposento alto para orar tres veces al día, con las ventanas abiertas hacia Jerusalén. Estos aposentos proporcionaban privacidad y quietud, siendo ideales para la oración y el estudio. Las ventanas orientadas al este permitían a Daniel orar hacia el sitio del templo, manteniendo su conexión con Jerusalén incluso en el exilio babilónico. Este detalle revela la vida devocional disciplinada de Daniel y su negativa a comprometer su testimonio público pese al decreto del rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5953', 'spa', 'obras, acciones, prácticas; usado para la conducta humana (especialmente obras perversas)', 'Este sustantivo denota obras, acciones o prácticas: la expresión concreta de las decisiones y el carácter humano. En Zacarías 1:4 aparece en el llamado profético al arrepentimiento: «Volveos de vuestros malos caminos y de vuestras malas obras». La palabra enfatiza el comportamiento real más que la mera intención, centrándose en los patrones de conducta que caracterizaron al Israel preexílico. Zacarías insta a la comunidad postexílica a aprender de la historia y evitar repetir las conductas que trajeron el juicio. El término frecuentemente lleva connotaciones negativas en la literatura profética, refiriéndose a prácticas perversas que violan el pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5953a', 'spa', 'Tratar con dureza, burlarse, abusar; más ampliamente, actuar contra alguien (con severidad u otro modo), ocuparse en prácticas.', 'Verbo que abarca desde la burla cruel hasta la noción más amplia de ''tratar con'' alguien. Sus apariciones más memorables involucran el abuso de poder: los actos poderosos de Dios contra Egipto para que Israel relatara ''cómo me burlé de ellos'' (Éx 10:2), la burra de Balaam preguntando ''¿qué te he hecho para que me golpees?'' (Nm 22:29), y el horrendo abuso en Guibeá (Jue 19:25). En Lamentaciones adopta un sentido más amplio de trato severo: ''hazles como me hiciste a mí'' (1:22). Las distinciones de conjugación verbal (Hitpael vs. Piel) conllevan diferentes intensidades de acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5953b', 'spa', 'rebuscar (uvas, aceitunas); figuradamente, recoger sobrevivientes como quien rebusca el fruto restante', 'Este verbo denominativo en Poel describe la práctica agrícola de rebuscar: recoger las uvas o aceitunas que quedan tras la cosecha principal. Levítico 19:10 y Deuteronomio 24:21 prohíben a los propietarios rebuscar sus propios viñedos, reservando lo restante para el pobre y el extranjero. Jeremías 6:9 emplea la imagen en sentido figurado con fuerza devastadora: rebuscarán como vid el remanente de Israel. En Jueces 20:45, el verbo se aplica a la guerra: los israelitas ''rebuscaron'' a los benjaminitas fugitivos, eliminándolos como quien despoja una vid.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5953c', 'spa', 'actuar como niño, comportarse infantilmente; usado para liderazgo inmaduro o irresponsable', 'Este verbo, formado a partir del sustantivo «niño», significa actuar infantilmente o comportarse como un niño. Isaías 3:12 lo emplea en una crítica mordaz: «Mi pueblo, su gobernante actúa como niño». El profeta acusa al liderazgo de Jerusalén de ser inmaduro, irresponsable e incapaz de gobernar. Esta acusación aparece en un pasaje que describe el colapso del liderazgo competente. El verbo capta la devastadora situación en que quienes ejercen la autoridad carecen de sabiduría, seriedad y capacidad: «juegan» a gobernar mientras la nación sufre las consecuencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5953d', 'spa', 'hundir, empujar hacia abajo con fuerza; usado metafóricamente para expresar humillación extrema', 'Este verbo significa introducir, hundir o empujar algo con fuerza hacia abajo. En Job 16:15 se usa metafóricamente: «He hundido mi cuerno en el polvo», expresando humillación y derrota absolutas. El cuerno simboliza fuerza y dignidad en la imaginería bíblica, de modo que hundirlo en el polvo representa un abatimiento total. La forma Poel sugiere acción intensiva. El lamento de Job describe su respuesta ante la pérdida devastadora y el sufrimiento: ha sido rebajado hasta el punto de empujar él mismo su dignidad al polvo, transmitiendo poderosamente su experiencia de degradación completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5954', 'spa', 'Entrar, ir adentro (básico); hacer entrar o introducir (causativo); ser traído ante alguien (pasivo). El verbo arameo ''alal funciona como el verbo pri', 'Entrar, ir adentro (básico); hacer entrar o introducir (causativo); ser traído ante alguien (pasivo). El verbo arameo ''alal funciona como el verbo principal de entrada en las porciones arameas de Daniel, reflejando al ubicuo hebreo bo''. En su raíz básica Peal, los sabios y astrólogos ''entran'' ante el rey (Dan 4:7; 5:8), y Daniel mismo entra para solicitar tiempo (Dan 2:16, 24). El Haphel causativo desplaza la agencia: Arioc ''hace entrar a Daniel'' ante Nabucodonosor (Dan 2:25), y el rey ordena que los encantadores sean ''hechos entrar'' para leer la escritura (Dan 5:7). El Hophal pasivo completa el conjunto cuando Daniel ''es traído'' ante Belsasar (Dan 5:13, 15) y el foso de los leones es sellado con la llegada del rey (Dan 6:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5955', 'spa', 'Rebusco, especialmente de uvas u olivas; los racimos sobrantes tras la cosecha, usado figuradamente para un pequeño remanente.', 'El sustantivo femenino plural עוֹלֵלוֹת (olelot) se refiere al rebusco de una viña o un olivar: los pequeños racimos que quedan después de la cosecha principal. Aunque el término es de origen agrícola, cada aparición bíblica lo emplea figuradamente: para un remanente devastado (Isa 17:6; 24:13), para la escasez de lo que los invasores dejan atrás (Jer 49:9 = Abd 5), y memorablemente, para el modesto logro de Gedeón que superó la vendimia completa de Efraín (Jue 8:2). El español ''rebusco'' captura con precisión este sentido agrícola que se extiende a lo metafórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5956', 'spa', 'Esconder, ocultar o estar oculto; en Hitpael, apartar la mirada deliberadamente; como sustantivo, cosas secretas u ocultas', 'Esconder, ocultar o estar oculto; en Hitpael, apartar la mirada deliberadamente; como sustantivo, cosas secretas u ocultas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5957', 'spa', 'Perpetuidad, eternidad; también tiempo antiguo o antigüedad. Cognado arameo del hebreo עוֹלָם. Este equivalente arameo del hebreo עוֹלָם aparece exclu', 'Perpetuidad, eternidad; también tiempo antiguo o antigüedad. Cognado arameo del hebreo עוֹלָם. Este equivalente arameo del hebreo עוֹלָם aparece exclusivamente en las porciones arameas de Daniel y Esdras. Su fuerza principal es prospectiva —apuntando hacia adelante en duración ilimitada. Cuando Daniel declara que el reino de Dios es ''un reino eterno'' (מַלְכוּת עָלַם, Daniel 3:33; 7:27), o cuando los cortesanos saludan al rey con ''¡vive para siempre!'' (לְעָלְמִין, Daniel 2:4), la palabra se extiende hacia un tiempo futuro sin límites. Sin embargo, en Esdras 4:15 y 4:19, mira hacia atrás: ''desde los días antiguos'' (מִן־יוֹמָת עָלְמָא), describiendo la antigua reputación rebelde de Jerusalén. La bidireccionalidad temporal queda perfectamente captada en Daniel 2:20: ''desde la eternidad hasta la eternidad'' (מִן־עָלְמָא וְעַד־עָלְמָא).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5959', 'spa', 'Mujer joven en edad de casarse; doncella, con connotaciones de virginidad en muchas tradiciones (cf. Is 7:14)', 'Este sustantivo designa a una mujer joven que ha alcanzado la edad para contraer matrimonio, con fuertes connotaciones de juventud y, en muchas tradiciones de traducción, virginidad. Su aparición más célebre es Isaías 7:14, donde la Septuaginta lo tradujo con el griego parthenos (''virgen''), moldeando siglos de interpretación mesiánica. En otros pasajes aparece de forma natural: Rebeca junto al pozo (Gn 24:43), Miriam vigilando al pequeño Moisés (Éx 2:8) y doncellas en procesiones festivas (Sal 68:25). La forma plural aparece en el Cantar de los Cantares para las ''doncellas'' que aman al novio (Cnt 1:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5960', 'spa', 'Almón, ciudad levítica en el territorio de Benjamín, idéntica a Alemet', 'Almón fue una de las ciudades asignadas a los levitas dentro de la herencia tribal de Benjamín. El pasaje paralelo en 1 Crónicas 6:60 la denomina Alemet, lo cual refleja la fluidez en la transmisión de los topónimos antiguos. Las variantes de la Septuaginta («Gamala», «Almón», «Elmón») ilustran aún más esta variación. Situada aproximadamente a una hora al noreste de Jerusalén, en la actual Almit, servía como una de las poblaciones donde residían los levitas, cumpliendo así el plan de distribuir a la tribu sacerdotal por todo el territorio de Israel, creando una red de instrucción religiosa y liderazgo entre todas las tribus.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5962', 'spa', 'elamitas, pueblo originario de Elam (suroeste de Irán); descendientes de Elam, hijo de Sem', 'Los elamitas eran habitantes de Elam, el antiguo reino situado al este de Mesopotamia, en lo que hoy es el suroeste de Irán. Elam aparece en Génesis 10 como uno de los hijos de Sem, lo que sitúa a los elamitas dentro de la familia semítica de naciones. Esdras 4:9 los menciona entre los pueblos reasentados a la fuerza en Samaria por el imperio asirio, como parte de la política de desplazamiento poblacional que creó la población mixta de la región. Los elamitas también aparecen en Hechos 2 durante Pentecostés, evidenciando su presencia continuada en el antiguo Cercano Oriente y el alcance de las conquistas imperiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5964', 'spa', 'Alemet; nombre personal benjaminita y ciudad levítica, significado incierto', 'Un nombre que aparece en dos contextos: como descendiente benjaminita en las genealogías y como ciudad levítica (también escrita Almón en otros pasajes). En 1 Crónicas 6-9, las listas genealógicas muestran variantes ortográficas que reflejan la transmisión textual. Las transliteraciones griegas de la LXX varían notablemente (Salamaith, Galemeth, Alamoth), lo que sugiere incertidumbre de los copistas respecto a la forma exacta. Como topónimo, designa una ciudad levítica en el territorio de Benjamín. La evidencia multilingüe muestra transliteración en lugar de traducción, como es habitual con los nombres propios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5965', 'spa', 'Regocijarse, deleitarse; expresar gozo mediante palabras o acciones festivas', 'Este raro verbo aparece solo tres veces, siempre expresando deleite gozoso o celebración exultante. Job 20:18 dice que el malvado «no se regocijará» con sus ganancias ilícitas, en paralelo con otros verbos de gozo. Job 39:13 describe el ala del avestruz «aleteando gozosamente», una imagen vívida de movimiento exuberante. Proverbios 7:18, de manera más provocadora, presenta a la adúltera invitando: «deleitémonos con amores», una celebración perversa del placer ilícito. Los tres contextos muestran el amplio espectro del gozo: satisfacción material, exuberancia natural y deleite sensual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5966', 'spa', 'sorber, tragar ávidamente (incierto); posible corrupción textual', 'Este verbo oscuro aparece únicamente en Job 39:30, describiendo cómo las crías del águila «sorben» o «tragan» sangre. Sin embargo, el texto es bastante incierto, y la mayoría de los eruditos sugieren que representa una corrupción textual de una forma del verbo לָעַע (tragar/engullir). El contexto describe la naturaleza feroz del águila: donde hay muertos, allí se encuentra, y sus crías devoran sangre con avidez. Sea que el verbo original fuera עָלַע o לָעַע, el significado converge en la imagen de un consumo voraz y ávido de la presa. El BDB lo registra como una raíz hipotética reconstruida a partir de este único pasaje difícil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5967', 'spa', 'costillas (arameo); los huesos curvos del torso o los costados del cuerpo', 'Este término arameo designa las costillas, los huesos que forman los costados de la cavidad torácica. Daniel 7:5 lo emplea al describir la segunda bestia de su visión: un oso con «tres costillas en su boca entre sus dientes». La imagen retrata a una criatura poderosa y carnívora devorando activamente a su presa, con costillas de sus víctimas aún alojadas entre sus fauces. Este detalle enfatiza la naturaleza voraz y destructiva de la bestia. En el simbolismo antiguo, imágenes tan vívidas representaban imperios y sus conquistas. El término es el equivalente arameo del hebreo צֵלָע, que puede significar costilla o costado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5968', 'spa', 'cubrir, envolver; desfallecer o desmayarse por agotamiento; reflexivamente, cubrirse con un velo', 'Este verbo abarca un arco semántico notable que va desde el cubrimiento físico hasta la pérdida del conocimiento. En el Pual, describe marfil ''recubierto de'' zafiros (Cnt 5:14) y personas que desfallecen en las esquinas de las calles por el hambre (Is 51:20). El Hitpael recoge a Tamar envolviéndose en un velo como disfraz (Gn 38:14) y a Jonás desmayándose por el viento abrasador del este (Jon 4:8). El hilo conductor es el envolvimiento, ya sea por tela, piedra preciosa o una sensación física abrumadora. El cognado árabe ghalafa (''enfundar, cubrir'') confirma el significado raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5969', 'spa', 'desmayarse, cubrirse; quedar envuelto o perder el sentido por agotamiento o confusión', 'Este verbo describe el acto de quedar cubierto, envuelto o con los sentidos nublados, ya sea por desmayo debido al agotamiento o por estar envuelto en confusión. En Ezequiel 31:15 se emplea metafóricamente para describir la reacción de los árboles del Edén cuando el gran cedro (Asiria) cayó: los árboles se desmayaron o quedaron cubiertos de luto. La imagen transmite una respuesta solidaria ante una caída catastrófica: toda la creación reacciona cuando el juicio golpea a los poderosos. El verbo abarca tanto el cubrimiento físico como el abrumamiento de la conciencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5970', 'spa', 'Exultar, regocijarse grandemente; gozo profundo y triunfal dirigido típicamente hacia Dios', 'Verbo en Qal que expresa un gozo exuberante y triunfal, más intenso que la alegría ordinaria, cercano a una exultación desbordante. Aparece casi exclusivamente en contextos de adoración y oración dirigidos a Dios. La oración de Ana ofrece el uso paradigmático: ''mi corazón se regocija en el SEÑOR'' (1 S 2:1). Los Salmos lo combinan con el canto y el gozo (Sal 5:11; 9:2; 68:3), mientras que Proverbios lo emplea para la alegría cívica cuando prosperan los justos (Pr 11:10; 28:12). Transmite una emoción celebratoria intensa y desbordante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5971', 'spa', 'el pueblo, la nación; usado para designar a Israel como pueblo del pacto de Dios', 'Esta es la palabra hebrea más común para pueblo o nación, y aparece miles de veces a lo largo del Antiguo Testamento. En Jeremías 17:19 se presenta con el artículo definido en la frase «puerta de los hijos del pueblo», refiriéndose a una puerta pública por donde pasaba la gente común. El término עַם puede designar a Israel como pueblo del pacto, a otras naciones o simplemente a una población. Enfatiza la identidad colectiva y el sentido de pertenencia compartida. Cuando se aplica a Israel, conlleva una profunda carga teológica: son «mi pueblo», ligados a Dios por promesa y obligación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5971a', 'spa', 'pueblo, nación, comunidad — cuerpo colectivo de personas, especialmente Israel o las naciones', 'El sustantivo עַם es el término principal de la Biblia hebrea para designar un cuerpo colectivo de personas, ya sea Israel («mi pueblo»), una nación extranjera o la humanidad en general. Aparece cerca de 1.840 veces, profundamente entretejido en el lenguaje de la alianza: Dios llama a Israel עַמִּי («mi pueblo», Éx 3:7) y a las naciones עַמִּים («pueblos»). Su raíz probablemente connota parentesco o vinculación, lo que lo distingue de גּוֹי, que enfatiza la condición de nación política o territorial. Todas las lenguas principales reflejan este significado colectivo: pueblo, peuple, Volk.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5971b', 'spa', 'Pariente, parentela; el pueblo o clan ancestral de uno, especialmente en la expresion ''reunido con sus pueblos''', 'Pariente, parentela; el pueblo o clan ancestral de uno, especialmente en la expresion ''reunido con sus pueblos''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5972', 'spa', 'Pueblo, nación (arameo); la población colectiva de un reino o grupo étnico en Daniel y Esdras.', 'Este sustantivo arameo ʿam funciona exactamente como su cognado hebreo, designando un pueblo o población nacional. Aparece en los decretos reales y visiones apocalípticas de Daniel y Esdras, donde los reyes babilonios y persas se dirigen a ''todos los pueblos, naciones y lenguas'' (Dn 3:4, 7; 5:19; 6:26; 7:14). El plural enfático ʿammayāʾ recurre en estas proclamaciones abarcadoras, mientras que el singular aparece en contextos como el decreto de Ciro referente a ''su pueblo'' (la nación judía, Esd 5:12; 6:12). Su restricción a contextos arameos cortesanos y visionarios le confiere un registro marcadamente imperial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5973a', 'spa', 'con, junto con; preposición de compañía, proximidad, oposición o posesión', 'La preposición עִם es uno de los vocablos más versátiles del hebreo bíblico; aparece casi mil veces para expresar la experiencia fundamental de estar «con» alguien. En su núcleo denota compañía: caminar con Dios, habitar con el prójimo, salir con un ejército. Sin embargo, al igual que su cognado árabe مَعَ y el arameo עִם, se extiende más allá de la simple unión. En pasajes llamativos se invierte para significar «contra», como cuando Moisés acusa a Israel de rebelión «con» el Señor (Dt 9:7). También se desliza hacia la proximidad espacial («junto a la encina de Siquem», Gn 35:4) o la posesión («hay forraje con nosotros», Gn 24:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5973b', 'spa', 'Preposición compuesta ''de junto a, de la presencia de'' (origen desde la cercanía o compañía de alguien); raramente comparativa ''más que lo que hay con', 'Preposición compuesta ''de junto a, de la presencia de'' (origen desde la cercanía o compañía de alguien); raramente comparativa ''más que lo que hay con''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5974', 'spa', 'Con, junto con — preposición aramea de acompañamiento, asociación o simultaneidad temporal', 'Con, junto con — preposición aramea de acompañamiento, asociación o simultaneidad temporal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5975', 'spa', 'Estar de pie, pararse; mantenerse firme, resistir; detenerse; apostar, designar; erigir, establecer; servir, asistir', 'Verbo fundamental de postura y posición en la Biblia hebrea, amad cubre el espectro completo desde el simple estar de pie hasta la resistencia metafórica, desde detenerse en seco hasta ser apostado en servicio oficial. Su Hifil causativo añade la dimensión de colocar a otros: designar un sacerdote, erigir un pilar, establecer un decreto. La raíz es profundamente pansemítica: el árabe amada significa apuntalar o sostener, el etiópico la conserva en el sustantivo ''pilar'' (amud) y el arameo ammuda porta el mismo sentido arquitectónico. En las traducciones, el abanico es notable: el español distingue pararse de permanecer y de establecer, reflejando los múltiples ejes del verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5976', 'spa', 'hacer temblar, desestabilizar; causar inestabilidad física o vacilación', 'Este verbo en forma Hifil significa hacer temblar, tambalear o vacilar, es decir, provocar inestabilidad en algo o alguien. En Ezequiel 29:7 se usa metafóricamente para ilustrar la falta de fiabilidad de Egipto como aliado: cuando Israel se apoyó en Egipto (representado como un bastón de caña), este se quebró e hizo tambalear sus espaldas. La imagen transmite con fuerza la traición política: en lugar de brindar apoyo, el fracaso de Egipto causó inestabilidad y daño. El verbo expresa la acción causativa de inducir inestabilidad en otro, y se relaciona con la raíz que significa resbalar o perder pie firme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5977', 'spa', 'Lugar donde uno se para, puesto asignado; posición fija para el culto, la asamblea o el encuentro divino.', 'El sustantivo עֹמֶד (omed) significa ''lugar donde uno se para'' o ''puesto asignado'', derivado de la raíz עמד (''estar de pie''). Aparece únicamente con sufijos y tras preposiciones (עַל־עָמְדָם, ''en su lugar''), y designa la posición fija donde una persona se sitúa para una ocasión formal. La mayoría de las ocurrencias describen puestos de culto o asamblea: los levitas y el pueblo de pie en sus lugares asignados durante las reformas de Ezequías y Josías (2 Cr 30:16; 34:31; 35:10), y el pueblo durante la lectura de la Torá por Esdras (Neh 8:7; 9:3; 13:11). Daniel lo utiliza para el sitio donde se encontraba durante su visión angélica (Dan 8:17-18; 10:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5978', 'spa', 'Conmigo; preposicion que expresa acompanamiento, proximidad, asociacion u oposicion hacia el hablante', 'Conmigo; preposicion que expresa acompanamiento, proximidad, asociacion u oposicion hacia el hablante');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5979', 'spa', 'lugar donde se está de pie, posición; el sitio donde uno se para o toma postura', 'Este sustantivo designa un lugar donde uno se para o una posición firme. En Miqueas 1:11 aparece en un texto difícil y debatido: «él tomará de vosotros su lugar de apoyo» o posiblemente «no tendréis lugar donde estar de pie». El pasaje forma parte de una serie de juegos de palabras con nombres de ciudades en los oráculos de juicio de Miqueas. La oscuridad del texto ha generado interpretaciones diversas, pero la idea central gira en torno a la pérdida de una posición segura: el pueblo no tendrá dónde mantenerse firme. El término se relaciona con el verbo עָמַד (estar de pie), enfatizando estabilidad y firmeza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5980', 'spa', 'Junto a, al lado de, paralelo a; correspondiente a, equivalente; enfrente en oposicion', 'Junto a, al lado de, paralelo a; correspondiente a, equivalente; enfrente en oposicion');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5981', 'spa', 'Uma, una ciudad en el territorio de Aser', 'Este nombre de lugar aparece únicamente en la lista de herencia tribal de Aser. El hebreo conserva el nombre con mínima variación entre las traducciones, lo que indica un topónimo bien establecido. BDB señala la ubicación en conexión con Aco, situándola en la región costera del norte asignada a Aser durante la conquista. Como nombre propio geográfico, se mantiene en su forma fonética original sin traducción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5982', 'spa', 'Columna, pilar — tanto soportes arquitectónicos como la columna teofánica de nube/fuego que guiaba a Israel', 'El hebreo ammud abarca dos realidades vívidas. Arquitectónicamente, designa las columnas portantes del tabernáculo, el templo de Salomón y edificaciones ordinarias: las mismas columnas que Sansón asió para derribar la casa de los filisteos (Jue 16:25-29). Pero la palabra adquiere fuerza numinosa en las narraciones del éxodo, donde la presencia de Dios se manifiesta como columna de nube de día y de fuego de noche, conduciendo a Israel por el desierto. Las traducciones multilingües hacen visible la distinción: los usos arquitectónicos producen ''columnas/pilares'', mientras que los teofánicos añaden consistentemente el constructo ''columna de'', marcando el tránsito de estructura a presencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5983', 'spa', 'Amón: pueblo, territorio y descendientes de Ben-Amí, hijo de Lot; casi siempre en la frase ''hijos de Amón''', 'Amón designa al pueblo y al territorio de los amonitas, tradicionalmente descendientes de Ben-Amí, hijo de Lot (Gn 19:38). Aparece casi siempre en la frase constructa בְּנֵי עַמּוֹן (''hijos de Amón'') y ocupa un lugar prominente en la historia militar y diplomática de Israel desde la conquista hasta la monarquía. Los amonitas habitaban al este del Jordán, al noreste de Moab, entre los ríos Arnón y Jaboc. Episodios clave incluyen las guerras de Jefté (Jue 10-12), el rescate de Jabés de Galaad por Saúl (1 S 11) y las campañas de David (2 S 10-12). Oráculos proféticos contra Amón figuran en Jeremías 49, Ezequiel 25 y Amós 1.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5984', 'spa', 'Amonita: adjetivo gentilicio para el pueblo de Amón, vecino oriental transjordano de Israel. Sustantivo y adjetivo gentilicio que identifica a los mie', 'Amonita: adjetivo gentilicio para el pueblo de Amón, vecino oriental transjordano de Israel. Sustantivo y adjetivo gentilicio que identifica a los miembros de la nación de Amón, un pueblo transjordano descendiente de la hija menor de Lot (Gn 19:38). El término aparece en formas singular, plural y femenina en textos legales, narrativos y proféticos. Deuteronomio excluye al amonita de la asamblea del Señor (Dt 23:3; Neh 13:1). Nahas el amonita amenaza a Jabés de Galaad (1 Sam 11:1-2), y las esposas extranjeras de Salomón incluyen mujeres amonitas, especialmente Naama, madre de Roboam (1 Re 14:21, 31; 11:1). En Nehemías, Tobías el amonita es un antagonista persistente en la obra de reconstrucción (Neh 2:10, 19; 3:35).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5985', 'spa', 'la amonita; gentilicio femenino que designa a mujeres oriundas de Amón, frecuente en contextos de matrimonios con extranjeras', 'Gentilicio femenino que identifica a mujeres provenientes de Amón, empleado en contextos monárquicos y genealógicos. Las cuatro apariciones se refieren a mujeres amonitas vinculadas a la realeza israelita: Naamá la amonita, madre del rey Roboam, figura tanto en los relatos de Reyes como de Crónicas. El término conlleva una crítica implícita en la teología bíblica, ya que los amonitas tenían prohibida la entrada a la asamblea y los matrimonios con ellos eran desalentados. El uso constante del gentilicio preserva tanto la identificación étnica como la especificidad de género.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5986', 'spa', 'Amós, profeta del siglo VIII a.C. de Tecoa, pastor llamado a profetizar contra la injusticia social de Israel', 'Amós es el nombre del pastor-profeta de Tecoa en Judá, llamado por Dios para pronunciar oráculos de juicio contra el reino del norte de Israel durante el reinado de Jeroboam II. Su nombre, que posiblemente significa ''portador de carga,'' se ajusta a su papel como portador de severos pronunciamientos proféticos contra la opresión social y el ritualismo vacío. Las siete apariciones del nombre se encuentran dentro del libro que lleva su nombre, y prácticamente todas las tradiciones de traducción lo transliteran de manera idéntica como Amós.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5988', 'spa', 'Amiel — nombre propio que significa ''mi pariente es Dios'', llevado por cuatro hombres distintos en el AT.', 'Un nombre teofórico que combina ''am (pariente, pueblo) con ''El (Dios), expresando la confesión ''mi pariente es Dios''. Cuatro individuos distintos llevan este nombre: un espía danita enviado a explorar Canaán (Núm 13:12), el padre de Maquir que albergó a Mefiboset en Lo-debar (2 Sam 9:4-5; 17:27), el padre de Betsabé (1 Cr 3:5, llamado Eliam en 2 Sam 11:3, los mismos dos elementos invertidos), y un portero levítico, hijo de Obed-edom (1 Cr 26:5). La etimología semítica transparente del nombre se refleja en su traducción consistente entre lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5989', 'spa', 'Amiud, nombre propio masculino que significa ''mi pariente es majestad'', portado por varios israelitas en Números y Crónicas.', 'Nombre hebreo teofórico (עַמִּיהוּד) que combina עַם (pariente, pueblo) y הוּד (majestad, esplendor), con el significado ''mi pariente es glorioso''. El más destacado de sus portadores fue Amiud, padre de Elisama, líder de la tribu de Efraín durante la travesía por el desierto (Nm 1:10; 2:18; 7:48, 53; 10:22). Otros portadores incluyen un jefe simeonita que ayudó a repartir la tierra de Canaán (Nm 34:20), un jefe neftalita con la misma función (Nm 34:28) y un judío mencionado en la genealogía postexílica (1 Cr 9:4). La Septuaginta lo transcribe variablemente como Σεμιουδ y Αμιουδ.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5990', 'spa', 'Amizabad, nombre propio que significa ''mi pariente ha otorgado''', 'Este nombre teofórico combina el término de parentesco עַמִּי (''mi pueblo'' o ''mi pariente'') con una raíz verbal relacionada con dar u otorgar. El nombre sigue un patrón común en los nombres compuestos hebreos que expresan relaciones familiares y bendición divina. Su portador es identificado como hijo de Benaía, uno de los comandantes militares de David, y aparece en las genealogías del libro de Crónicas dentro de la organización militar del rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5992', 'spa', 'Aminadab; nombre propio que significa ''mi pariente es noble'', llevado por el suegro de Aarón y otros.', 'El nombre teofórico Aminadab (ammi, ''mi pariente'' + nadav, ''es noble/generoso'') designa a varias figuras bíblicas, principalmente al suegro del sumo sacerdote Aarón y antepasado de David. Como padre de Naasón, jefe tribal de Judá durante el período del desierto (Nm 1:7; 2:3; 7:12, 17; 10:14), Aminadab ocupa una posición clave en la genealogía que va desde Judá hasta David (Rt 4:19–20; 1 Cr 2:10) y finalmente hasta Jesús en la genealogía de Mateo. El nombre también pertenece a levitas mencionados en 1 Crónicas 6:7 y 15:10–11.');